import type { ChapterStudy, StudyConnection, TheologyPoint, VerseStudy } from "./studies";

function v(
  number: number,
  title: string,
  summary: string,
  hebrew: string,
  transliteration: string,
  exegesis: string,
  language: string,
): VerseStudy {
  return {
    number,
    title,
    summary,
    hebrew,
    transliteration,
    rvr: "Lectura tradicional: " + summary,
    ntv: "En lenguaje contemporáneo: " + summary,
    lbla: "Énfasis textual: " + summary,
    exact: false,
    exegesis,
    language,
  };
}

function c(
  chapter: number,
  title: string,
  introduction: string,
  verses: VerseStudy[],
  theology: TheologyPoint[],
  doctrinalNote: string,
  connections: StudyConnection[],
): ChapterStudy {
  return {
    key: "GEN-" + chapter,
    bookId: "GEN",
    bookSlug: "genesis",
    bookName: "Génesis",
    testament: "Antiguo Testamento",
    section: "Pentateuco",
    chapter,
    chapterCount: 50,
    lessonLabel: "Lección " + chapter,
    title,
    introduction,
    verses,
    theology,
    doctrinalNote,
    connections,
  };
}

const genesis3 = c(
  3,
  "La caída y la promesa",
  "Génesis 3 explica la entrada del pecado en la experiencia humana: la palabra de Dios es distorsionada, la confianza se rompe y la creación queda herida. En medio del juicio aparece también una promesa de victoria y el cuidado persistente del Creador.",
  [
    v(1, "La pregunta que distorsiona", "La serpiente, descrita como astuta, cuestiona la generosidad y la palabra de Dios.", "אַף כִּי־אָמַר אֱלֹהִים", "Af ki-amar Elohim", "La tentación comienza exagerando la prohibición para presentar a Dios como restrictivo. El relato identifica a la serpiente como criatura; la revelación posterior relacionará su obra con el adversario.", "Arum, «astuto», hace juego con arummim, «desnudos», de 2:25. La inocencia humana es confrontada por una astucia orientada al engaño."),
    v(2, "La mujer recuerda la libertad", "La mujer responde que pueden comer del fruto de los árboles del jardín.", "מִפְּרִי עֵץ־הַגָּן נֹאכֵל", "Mipperi ets-hagan nokhel", "Su primera frase conserva la amplitud del permiso divino. Sin embargo, la respuesta siguiente mostrará que el mandato ya empieza a ser reformulado.", "Nokhel, «podemos comer», contrasta con la insinuación de una prohibición total."),
    v(3, "El mandato reformulado", "La mujer identifica el árbol prohibido, añade no tocarlo y recuerda el peligro de muerte.", "וְלֹא תִגְּעוּ בּוֹ", "Velo tiggu vo", "Dios había prohibido comer, no tocar. La adición puede reflejar una protección humana, pero altera la formulación recibida y deja espacio para que el engaño ataque su credibilidad.", "Tiggu procede de naga, «tocar». Pen temutun expresa «para que no mueran», menos enfático que el anuncio divino de 2:17."),
    v(4, "La negación frontal", "La serpiente contradice directamente la advertencia divina y asegura que no morirán.", "לֹא־מוֹת תְּמֻתוּן", "Lo-mot temutun", "El engaño avanza de la duda a la negación. El tentador promete impunidad y separa la elección moral de sus consecuencias.", "La construcción repite mot tamut, pero la precede con lo, «no», invirtiendo deliberadamente la palabra de Dios."),
    v(5, "La promesa de autonomía", "La serpiente promete ojos abiertos y conocimiento semejante al divino.", "וִהְיִיתֶם כֵּאלֹהִים", "Vihyitem kElohim", "La tentación mezcla una verdad parcial con una conclusión falsa: sus ojos se abrirán, pero no alcanzarán libertad divina; conocerán el mal por participación culpable.", "Elohim puede entenderse «Dios» o «seres divinos». Yodee tov vara describe conocimiento del bien y del mal."),
    v(6, "Deseo, decisión y participación", "La mujer contempla el fruto, lo toma, come y lo comparte con su marido, que también come.", "וַתִּקַּח מִפִּרְיוֹ וַתֹּאכַל", "Vattiqaj mippiryo vattokhal", "La secuencia visual, apetitiva y sapiencial muestra cómo el deseo redefine lo bueno al margen de Dios. El hombre está presente y participa sin resistencia.", "Taavah es «deseo»; nejmad, «codiciable»; lehaskil, «para alcanzar sabiduría». Los verbos consecutivos aceleran la acción."),
    v(7, "Ojos abiertos y vergüenza", "Ambos reconocen su desnudez y fabrican coberturas con hojas de higuera.", "וַיֵּדְעוּ כִּי עֵירֻמִּם הֵם", "Vayyedeu ki eirummim hem", "La promesa de ojos abiertos se cumple de forma amarga. La primera reacción es ocultar la vulnerabilidad, señal de una relación fracturada consigo mismos y entre sí.", "Yadeu, «conocieron», comunica experiencia. Jagorot son coberturas o cinturones improvisados."),
    v(8, "La presencia evitada", "Al oír a Dios en el jardín, el hombre y la mujer se esconden entre los árboles.", "וַיִּתְחַבֵּא הָאָדָם וְאִשְׁתּוֹ", "Vayyitjabe haadam veishto", "La presencia que debía ser comunión provoca temor. El pecado no elimina la iniciativa divina: Dios se acerca, mientras la humanidad intenta desaparecer.", "Mitjallekh describe a Dios «paseándose». Leruaj hayom puede significar «al aire del día» o «a la brisa»."),
    v(9, "¿Dónde estás?", "Dios llama al hombre y le pregunta por su ubicación.", "אַיֶּכָּה", "Ayekkah", "La pregunta no busca información geográfica, sino que convoca al ser humano a presentarse y responder. Es una invitación judicial y relacional.", "Ayekkah, «¿dónde estás?», se dirige en singular al hombre como responsable interpelado."),
    v(10, "Temor y ocultamiento", "El hombre confiesa que tuvo miedo por estar desnudo y se escondió.", "וָאִירָא כִּי־עֵירֹם אָנֹכִי", "Vaira ki-eirom anokhi", "La vergüenza se expresa como miedo. El hombre menciona su desnudez, pero aún no reconoce la desobediencia que produjo su nueva condición.", "Yare significa «temer». Anokhi enfatiza el yo: la atención se concentra ahora en la autoprotección."),
    v(11, "La palabra revela la desobediencia", "Dios pregunta quién informó de la desnudez y si comió del árbol prohibido.", "הֲמִן־הָעֵץ אֲשֶׁר צִוִּיתִיךָ", "Hamin-haets asher tsivitikha", "Dios conecta la experiencia de vergüenza con el mandato quebrantado. La pregunta abre espacio para confesión, no porque Dios ignore lo ocurrido.", "Tsivitikha viene de tsavah, «mandar». La pregunta hebrea espera que el acusado confronte su acción."),
    v(12, "La culpa desplazada", "El hombre responsabiliza a la mujer y, de manera indirecta, a Dios que se la dio.", "הָאִשָּׁה אֲשֶׁר נָתַתָּה עִמָּדִי", "Haishah asher natattah immadi", "La comunión de 2:23 se convierte en acusación. Aunque reconoce que comió, el hombre enmarca el acto como consecuencia de los dones de otros.", "Natattah, «tú diste», coloca énfasis en Dios; hi natnah, «ella dio», lo traslada a la mujer."),
    v(13, "Engaño reconocido", "La mujer afirma que la serpiente la engañó y admite que comió.", "הַנָּחָשׁ הִשִּׁיאַנִי", "Hannajash hishiani", "La mujer identifica correctamente el engaño, pero la seducción no elimina su responsabilidad. La confesión sigue acompañada de explicación.", "Nasha en esta forma significa «engañar» o «seducir». Pablo retomará el término al comentar el episodio."),
    v(14, "Juicio sobre la serpiente", "La serpiente es maldita a arrastrarse y comer polvo durante su vida.", "אָרוּר אַתָּה", "Arur attah", "El juicio humilla al instrumento del engaño. Comer polvo es imagen de derrota, no una explicación biológica exhaustiva del movimiento de las serpientes.", "Arur, «maldito», se aplica directamente a la serpiente. Al-gajonekha significa «sobre tu vientre»."),
    v(15, "Enemistad y descendencia victoriosa", "Dios anuncia conflicto entre la serpiente y la mujer, y entre sus descendencias; la cabeza será herida aunque el talón sufra.", "הוּא יְשׁוּפְךָ רֹאשׁ", "Hu yeshufkha rosh", "El versículo establece enemistad y esperanza dentro del juicio. La lectura cristiana ve aquí el primer anuncio de la victoria mesiánica: el descendiente sufre, pero derrota decisivamente al enemigo.", "Zera puede ser descendencia colectiva o un descendiente representativo. Shuf aparece para ambas heridas; cabeza y talón marcan resultados desiguales."),
    v(16, "Dolor y conflicto relacional", "La maternidad estará marcada por dolor y la relación matrimonial por deseo y dominio.", "וְהוּא יִמְשָׁל־בָּךְ", "Vehu yimshal-bakh", "El texto describe consecuencias del pecado, no un ideal que deba celebrarse. Fecundidad y comunión continúan, pero ahora atraviesan sufrimiento y lucha por control.", "Itsavon incluye dolor y penosa labor. Teshuqah y mashal reaparecen en 4:7, vinculando deseo y dominio."),
    v(17, "La tierra bajo maldición", "Por escuchar la voz de su mujer contra el mandato, el hombre enfrentará trabajo penoso en suelo maldito.", "אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךָ", "Arurah haadamah baavurekha", "La vocación de trabajar permanece, pero el suelo ya no responde sin resistencia. El juicio alcanza la relación entre adam y adamah.", "Baavurekha significa «por causa de ti». Itsavon enlaza el dolor del trabajo con el de la maternidad."),
    v(18, "Espinas en el campo", "La tierra producirá espinos y cardos mientras el hombre come plantas del campo.", "וְקוֹץ וְדַרְדַּר", "Veqots vedardar", "La creación buena no se vuelve totalmente mala, pero su productividad queda mezclada con frustración. Las espinas serán después símbolo bíblico de desorden y juicio.", "Qots y dardar forman una pareja sonora: «espino y cardo»."),
    v(19, "Sudor, pan y retorno al polvo", "El hombre obtendrá alimento con esfuerzo hasta regresar a la tierra de la que fue tomado.", "כִּי־עָפָר אַתָּה וְאֶל־עָפָר תָּשׁוּב", "Ki-afar attah veel-afar tashuv", "La mortalidad anunciada en 2:17 queda explicitada. El trabajo produce pan, pero no vence la muerte; la criatura retorna al polvo sin dejar de depender del Creador.", "Afar, «polvo», encuadra la frase. Tashuv, «volverás», expresa el destino corporal."),
    v(20, "Eva, madre de los vivientes", "Adán llama Eva a su mujer porque será madre de todos los vivientes.", "וַיִּקְרָא הָאָדָם שֵׁם אִשְׁתּוֹ חַוָּה", "Vayiqra haadam shem ishto Javvah", "El nombre expresa esperanza después del anuncio de muerte. La vida humana continuará por la misericordia de Dios y mediante la descendencia prometida.", "Javvah se relaciona con jayah, «vivir». El juego de palabras explica el significado teológico del nombre."),
    v(21, "Dios cubre la vergüenza", "Dios hace vestiduras de piel para el hombre y la mujer y los viste.", "כָּתְנוֹת עוֹר", "Kotenot or", "Las coberturas humanas son sustituidas por una provisión divina más duradera. El texto muestra cuidado en medio del juicio; no declara explícitamente un sacrificio, aunque algunos perciben una anticipación.", "Kotenot son túnicas; or significa «piel». Vayalbishem, «los vistió», presenta a Dios como sujeto del cuidado."),
    v(22, "El acceso a la vida es restringido", "Dios declara que el ser humano conoce el bien y el mal y evita que coma del árbol de la vida para siempre.", "פֶּן־יִשְׁלַח יָדוֹ", "Pen-yishlaj yado", "La expulsión contiene juicio y misericordia: vivir eternamente en estado caído no sería restauración. El acceso a la vida requerirá la obra redentora que el canon desarrollará.", "Keajad mimmennu puede traducirse «como uno de nosotros». Leolam significa «para siempre»."),
    v(23, "Fuera del jardín", "Dios expulsa al hombre para cultivar el suelo del que fue formado.", "וַיְשַׁלְּחֵהוּ יְהוָה אֱלֹהִים", "Vayeshallejehu Adonai Elohim", "La vocación continúa fuera del santuario, pero ahora bajo exilio y dificultad. La humanidad pierde el acceso inmediato al jardín, no la responsabilidad sobre la tierra.", "Shalaj, «enviar», puede tomar fuerza de expulsión por el contexto. La repetición de adamah recuerda el origen humano."),
    v(24, "El camino guardado", "Querubines y una espada flameante custodian el camino al árbol de la vida.", "לִשְׁמֹר אֶת־דֶּרֶךְ עֵץ הַחַיִּים", "Lishmor et-derekh ets hajayyim", "El capítulo termina al este del jardín con acceso cerrado. Querubines aparecerán junto a espacios santos; el canon culminará con el árbol nuevamente accesible en la nueva creación.", "Shamar, «guardar», era tarea humana en 2:15 y ahora corresponde a guardianes celestiales. Derekh es «camino»."),
  ],
  [
    { title: "El pecado desconfía de Dios", text: "La rebelión nace al considerar insuficiente o falsa la palabra generosa del Creador." },
    { title: "La culpa rompe relaciones", text: "Vergüenza, ocultamiento y acusación sustituyen la transparencia original." },
    { title: "El juicio alcanza toda la vida", text: "Cuerpo, matrimonio, trabajo, tierra y mortalidad quedan afectados." },
    { title: "La gracia habla dentro del juicio", text: "La descendencia prometida, la vida continuada y las vestiduras muestran misericordia." },
  ],
  "Génesis 3 no enseña que la materia, la sexualidad o el trabajo sean malos en sí mismos. Describe cómo el pecado desordena dones creados como buenos. La identificación plena del vencedor de 3:15 se desarrolla progresivamente y alcanza su claridad en Cristo dentro del canon cristiano.",
  [
    ["Romanos 5:12–19", "Pablo contrasta la desobediencia de Adán con la obediencia representativa de Cristo."],
    ["2 Corintios 11:3", "La serpiente y su engaño sirven como advertencia sobre una mente apartada de la devoción a Cristo."],
    ["Hebreos 2:14", "Cristo vence mediante su muerte al que tenía el poder de la muerte."],
    ["Apocalipsis 12:9", "La serpiente antigua es identificada con el diablo y Satanás."],
    ["Apocalipsis 22:1–5", "La historia culmina con el árbol de la vida accesible y la maldición removida."],
  ],
);

const genesis4 = c(
  4,
  "Caín, Abel y la expansión del pecado",
  "Génesis 4 muestra cómo la ruptura con Dios se extiende a la fraternidad, la sociedad y la cultura. Junto al homicidio y la venganza aparecen adoración, trabajo, creatividad, protección misericordiosa y una nueva línea de esperanza.",
  [
    v(1, "Un hijo recibido con ayuda de Dios", "Eva concibe y da a luz a Caín, reconociendo la participación del Señor.", "קָנִיתִי אִישׁ אֶת־יְהוָה", "Qaniti ish et-Adonai", "El nacimiento manifiesta continuidad de vida después del exilio. La expresión hebrea es difícil, pero claramente relaciona el don del hijo con la acción de Dios.", "Qaniti significa «he adquirido» o «he producido» y crea un juego sonoro con Qayin, Caín."),
    v(2, "Dos hermanos y dos oficios", "Nace Abel; él pastorea rebaños y Caín trabaja la tierra.", "הֶבֶל ... קַיִן", "Hevel ... Qayin", "Los oficios son legítimos y complementarios; el relato no desprecia agricultura ni pastoreo. El conflicto surgirá de la disposición moral, no de la profesión.", "Hevel significa «soplo» o «vapor», anticipando literariamente la brevedad de su vida."),
    v(3, "Caín presenta una ofrenda", "Al cabo del tiempo, Caín lleva al Señor productos de la tierra.", "מִנְחָה לַיהוָה", "Minjah laAdonai", "La ofrenda reconoce formalmente a Dios como dador de la cosecha. El versículo por sí solo no indica que una ofrenda vegetal sea inaceptable.", "Minjah es «tributo», «don» u «ofrenda» y puede designar ofrendas vegetales legítimas en la Ley."),
    v(4, "Abel ofrece lo primero y mejor", "Abel presenta primogénitos y porciones selectas; Dios mira favorablemente a Abel y su ofrenda.", "מִבְּכֹרוֹת צֹאנוֹ וּמֵחֶלְבֵהֶן", "Mibbekhorot tsono umejelvehen", "La narración destaca primero al oferente y después la ofrenda. Hebreos explicará que Abel actuó por fe; la calidad de lo ofrecido expresa esa confianza.", "Bekhorot son «primogénitos» y jelev puede señalar la grasa o la porción más rica."),
    v(5, "Ira ante el rechazo", "Dios no mira favorablemente a Caín y su ofrenda; Caín se enfurece y decae su rostro.", "וַיִּחַר לְקַיִן מְאֹד", "Vayyijar leQayin meod", "El rechazo revela y prueba el corazón de Caín. En vez de buscar corrección, interpreta la situación desde resentimiento.", "Jarah describe ira encendida. Neflu fanav, «cayó su rostro», comunica abatimiento visible."),
    v(6, "Dios confronta la ira", "El Señor pregunta a Caín por su enojo y su semblante caído.", "לָמָּה חָרָה לָךְ", "Lammah jarah lakh", "Como en Génesis 3, la pregunta divina invita a examinarse y responder antes de que el pecado avance. Caín recibe una oportunidad real de rectificación.", "Lammah, «¿por qué?», dirige la atención hacia la motivación interior."),
    v(7, "El pecado acecha a la puerta", "Dios afirma que hacer lo bueno trae aceptación, pero el pecado desea dominar y debe ser gobernado.", "לַפֶּתַח חַטָּאת רֹבֵץ", "Lappetaj jattat rovets", "El pecado es retratado como animal agazapado. Caín no es una víctima inevitable: es llamado a dominar el impulso antes de que se convierta en violencia.", "Seet puede significar «ser levantado» o «ser aceptado». Teshuqah y mashal enlazan con 3:16."),
    v(8, "El primer fratricidio", "Caín lleva a Abel al campo, se levanta contra él y lo mata.", "וַיָּקָם קַיִן אֶל־הֶבֶל אָחִיו", "Vayyaqom Qayin el-Hevel ajiv", "El pecado contra Dios se manifiesta como destrucción del hermano. La repetición «su hermano» intensifica la traición de la relación.", "Harag es «matar». El texto hebreo presenta una dificultad donde algunas versiones añaden una invitación a ir al campo."),
    v(9, "¿Soy guardián de mi hermano?", "Dios pregunta por Abel; Caín miente y rechaza responsabilidad fraterna.", "הֲשֹׁמֵר אָחִי אָנֹכִי", "Hashomer aji anokhi", "La respuesta combina falsedad y desafío. El verbo «guardar», usado para el jardín, ahora define la responsabilidad negada hacia el prójimo.", "Shomer viene de shamar, «guardar» o «cuidar». Aji, «mi hermano», aparece irónicamente en la negación."),
    v(10, "La sangre que clama", "Dios declara que la sangre de Abel grita desde la tierra.", "קוֹל דְּמֵי אָחִיךָ צֹעֲקִים", "Qol demei ajikha tsoaqim", "El homicidio no queda oculto: la creación misma testifica contra la violencia. Dios escucha la vida inocente arrebatada.", "Demei es plural, «sangres», quizá intensivo o alusivo a la descendencia truncada. Tsaaq expresa clamor por justicia."),
    v(11, "Maldito desde la tierra", "Caín queda bajo maldición en relación con el suelo que recibió la sangre de Abel.", "אָרוּר אָתָּה מִן־הָאֲדָמָה", "Arur attah min-haadamah", "La tierra que debía ser cultivada se convierte en testigo y agente del juicio. Caín es el primer humano llamado directamente maldito.", "Patsah et-piha, «abrió su boca», personifica el suelo."),
    v(12, "Productividad perdida y desarraigo", "La tierra ya no dará su fuerza a Caín, que será errante y fugitivo.", "נָע וָנָד תִּהְיֶה בָאָרֶץ", "Na vanad tihyeh vaarets", "El agricultor pierde estabilidad y fruto. El juicio corresponde a su crimen: quien destruyó el lugar de su hermano pierde su propio lugar.", "Na vanad reúne términos próximos: «vagabundo y fugitivo»."),
    v(13, "Una carga insoportable", "Caín declara que su castigo o culpa es demasiado grande para soportarlo.", "גָּדוֹל עֲוֹנִי מִנְּשֹׂא", "Gadol avoni minneso", "La ambigüedad permite oír tanto culpa como pena. Caín lamenta principalmente las consecuencias, sin una confesión explícita del mal cometido.", "Avon puede significar «iniquidad», «culpa» o «castigo de la culpa»."),
    v(14, "Temor a la violencia", "Caín teme quedar oculto de la presencia divina y ser asesinado por quien lo encuentre.", "וּמִפָּנֶיךָ אֶסָּתֵר", "Umippanekha essater", "El homicida teme la misma violencia que introdujo. Aun así reconoce que la pérdida de la presencia divina es central a su exilio.", "Mistater, «ocultarse», recuerda el escondite de Génesis 3."),
    v(15, "Una señal de protección", "Dios limita la venganza, promete retribución séptuple y coloca una señal para proteger a Caín.", "שִׁבְעָתַיִם יֻקָּם", "Shivataim yuqqam", "La protección no absuelve a Caín; restringe la multiplicación privada de violencia. La señal concreta no se identifica y no debe asociarse a rasgos étnicos.", "Ot es «señal», no necesariamente marca corporal. Shivataim comunica una retribución plena o séptuple."),
    v(16, "Al oriente de Edén", "Caín sale de la presencia del Señor y habita en la tierra de Nod.", "מִלִּפְנֵי יְהוָה", "Millifnei Adonai", "El movimiento al este continúa el patrón de alejamiento del santuario. Nod se relaciona literariamente con el vagar anunciado.", "Nod juega con nad, «errante». La frase «presencia del Señor» subraya la dimensión espiritual."),
    v(17, "Familia y ciudad", "Caín tiene un hijo llamado Enoc y construye una ciudad con su nombre.", "וַיְהִי בֹּנֶה עִיר", "Vayehi boneh ir", "La ciudad expresa creatividad y búsqueda de seguridad, pero también contrasta con la condición errante decretada. La cultura humana puede contener logros y ambigüedad moral.", "Boneh es participio, «estaba construyendo», quizá indicando un proceso continuo."),
    v(18, "La línea de Caín continúa", "La genealogía avanza desde Enoc hasta Lamec.", "וַיִּוָּלֵד לַחֲנוֹךְ אֶת־עִירָד", "Vayyivaled laJanokh et-Irad", "La sucesión rápida muestra expansión humana sin evaluar a cada individuo. Conduce literariamente a Lamec, donde la violencia se intensifica.", "Las formas con yalad, «engendrar», estructuran la genealogía."),
    v(19, "Lamec toma dos mujeres", "Lamec rompe el patrón de una sola carne al tomar dos esposas, Ada y Zila.", "וַיִּקַּח־לוֹ לֶמֶךְ שְׁתֵּי נָשִׁים", "Vayiqaj-lo Lemekh shetei nashim", "Es la primera poligamia registrada. El narrador no añade aprobación; la ubicación dentro de la línea de creciente autonomía es significativa.", "Laqaj, «tomó», y shetei nashim, «dos mujeres», destacan la iniciativa de Lamec."),
    v(20, "Jabal y la vida pastoril", "Jabal es presentado como antepasado de quienes habitan en tiendas y crían ganado.", "אֲבִי יֹשֵׁב אֹהֶל וּמִקְנֶה", "Avi yoshev ohel umiqqneh", "La especialización productiva es un desarrollo cultural legítimo incluso dentro de una humanidad caída. La gracia común permite organización y conocimiento.", "Avi puede señalar «fundador» o «antepasado» de una forma de vida."),
    v(21, "Jubal y la música", "Jubal es presentado como antepasado de quienes tocan instrumentos de cuerda y viento.", "כָּל־תֹּפֵשׂ כִּנּוֹר וְעוּגָב", "Kol-tofes kinnor veugav", "La música aparece como capacidad humana desarrollada. El texto no la reduce a entretenimiento ni la condena por surgir en esta genealogía.", "Kinnor es lira; ugav probablemente instrumento de viento. Tofes significa quien maneja o toca."),
    v(22, "Tubal-caín y la metalurgia", "Tubal-caín trabaja herramientas de bronce y hierro; se menciona también a Naamá.", "לֹטֵשׁ כָּל־חֹרֵשׁ נְחֹשֶׁת וּבַרְזֶל", "Lotesh kol-joresh nejoshet uvarzel", "La tecnología amplía la capacidad de cultivar y construir, pero también puede servir a la violencia celebrada por Lamec. La técnica no determina su uso moral.", "Lotesh es «forjador» o «afilador»; nejoshet y barzel son bronce e hierro."),
    v(23, "La canción de la violencia", "Lamec presume ante sus esposas de haber matado a un hombre por herirlo.", "כִּי אִישׁ הָרַגְתִּי לְפִצְעִי", "Ki ish haragti lefitsi", "El homicidio de Caín produjo temor; Lamec convierte la violencia en poesía de orgullo. La desproporción revela una cultura de venganza.", "Haazennah, «escuchen», introduce un canto solemne. Petsa y javurah son herida y golpe."),
    v(24, "Venganza multiplicada", "Lamec reclama una venganza de setenta y siete veces frente a las siete de Caín.", "שִׁבְעִים וְשִׁבְעָה", "Shivim veshivah", "La protección limitadora de Dios es apropiada como derecho personal ilimitado. Jesús invertirá esta lógica al llamar al perdón repetido.", "La expresión puede leerse «setenta y siete» o «setenta veces siete»; el énfasis es intensificación."),
    v(25, "Seth como descendencia concedida", "Eva da a luz a Seth y reconoce que Dios ha provisto otra descendencia en lugar de Abel.", "שָׁת־לִי אֱלֹהִים זֶרַע אַחֵר", "Shat-li Elohim zera ajer", "La esperanza no continúa mediante la violencia de Caín, sino por una nueva provisión divina. El término descendencia enlaza con la promesa de 3:15.", "Shet se relaciona con shat, «puso» o «concedió». Zera es «descendencia»."),
    v(26, "Invocar el nombre del Señor", "A Seth le nace Enós y entonces se comienza a invocar públicamente el nombre del Señor.", "אָז הוּחַל לִקְרֹא בְּשֵׁם יְהוָה", "Az hujal liqro beshem Adonai", "El capítulo termina con adoración comunitaria como contrapunto a la autosuficiencia y la violencia. La línea de esperanza se caracteriza por dependencia confesada.", "Qara beshem significa «invocar» o «proclamar el nombre». Hujal puede indicar que se comenzó."),
  ],
  [
    { title: "La adoración compromete al adorador", text: "Dios mira a la persona y su ofrenda; el rito no sustituye la fe y la obediencia." },
    { title: "Somos responsables del hermano", text: "La pregunta de Caín recibe respuesta en toda la ética bíblica del amor al prójimo." },
    { title: "Dios limita la violencia", text: "El juicio divino no autoriza venganza privada ilimitada." },
    { title: "La cultura es moralmente responsable", text: "Ciudad, ganadería, música y metalurgia son capacidades que pueden servir vida o dominio violento." },
  ],
  "El rechazo de la ofrenda de Caín no debe explicarse simplemente porque fuera vegetal; la Ley aceptará ofrendas de cereal. El texto y Hebreos 11 dirigen la atención a la fe, la calidad de la entrega y la respuesta moral del oferente.",
  [
    ["Hebreos 11:4", "La fe distingue la ofrenda de Abel y mantiene vivo su testimonio."],
    ["1 Juan 3:11–12", "Caín representa el odio que se opone al amor fraternal."],
    ["Hebreos 12:24", "La sangre de Jesús habla una palabra superior a la sangre de Abel."],
    ["Mateo 18:21–22", "Jesús transforma la cifra de Lamec en una llamada al perdón abundante."],
  ],
);

const genesis5 = c(
  5,
  "De Adán a Noé",
  "Génesis 5 sigue la línea de Adán mediante Seth hasta Noé. La repetición «y murió» confirma el juicio de Génesis 3, mientras nacimientos, bendición y la excepción de Enoc preservan la esperanza de comunión y vida.",
  [
    v(1, "El libro de las generaciones de Adán", "La genealogía comienza recordando que Dios creó al ser humano a su semejanza.", "זֶה סֵפֶר תּוֹלְדֹת אָדָם", "Zeh sefer toledot Adam", "La historia posterior a la caída permanece dentro del propósito creador. La imagen divina no desaparece, aunque la humanidad viva bajo muerte.", "Sefer puede ser «libro» o «registro». Toledot introduce una nueva sección literaria."),
    v(2, "Varón y mujer bajo bendición", "Dios creó varón y mujer, los bendijo y los llamó humanidad.", "זָכָר וּנְקֵבָה בְּרָאָם", "Zakhar uneqevah beraam", "La genealogía reafirma la dignidad compartida y la bendición de Génesis 1. Adam funciona aquí como nombre colectivo de la humanidad.", "Beraam significa «cuando los creó». Vayiqra et-shemam Adam: «llamó el nombre de ellos humanidad»."),
    v(3, "Seth en semejanza de Adán", "A los ciento treinta años, Adán engendra a Seth en su semejanza e imagen.", "בִּדְמוּתוֹ כְּצַלְמוֹ", "Bidmuto ketsalmo", "La imagen recibida de Dios se transmite dentro de una humanidad ahora mortal. Seth comparte dignidad y también la condición histórica de su padre.", "Demut y tselem repiten «semejanza» e «imagen» de 1:26."),
    v(4, "La familia de Adán se multiplica", "Después del nacimiento de Seth, Adán vive ochocientos años y tiene otros hijos e hijas.", "וַיּוֹלֶד בָּנִים וּבָנוֹת", "Vayoled banim uvanot", "La genealogía selecciona una línea sin negar una población más amplia. Los otros descendientes explican el crecimiento humano presupuesto en capítulos anteriores.", "Banim uvanot es una fórmula recurrente: «hijos e hijas»."),
    v(5, "Adán muere", "La vida de Adán alcanza novecientos treinta años y termina con su muerte.", "וַיָּמֹת", "Vayamot", "La frase confirma la advertencia divina: aun una longevidad extraordinaria termina bajo el poder de la muerte. Se inicia el estribillo solemne del capítulo.", "Vayamot, «y murió», cerrará casi cada generación."),
    v(6, "Seth engendra a Enós", "Seth tiene ciento cinco años cuando nace Enós.", "וַיּוֹלֶד אֶת־אֱנוֹשׁ", "Vayoled et-Enosh", "La línea concedida en lugar de Abel continúa. Cada nacimiento sostiene la promesa en un mundo donde cada generación muere.", "Enosh puede relacionarse con humanidad frágil o mortal."),
    v(7, "Los años posteriores de Seth", "Seth vive ochocientos siete años después de Enós y tiene hijos e hijas.", "שְׁמֹנֶה מֵאוֹת שָׁנָה", "Shemoneh meot shanah", "La fórmula amplía la familia sin convertir el registro en una lista exhaustiva. El énfasis recae en continuidad generacional.", "Shanah es «año»; los números forman parte del diseño genealógico del texto."),
    v(8, "La muerte de Seth", "Seth muere después de vivir novecientos doce años.", "וַיִּהְיוּ כָּל־יְמֵי־שֵׁת", "Vayihyu kol-yemei-Shet", "La línea piadosa no escapa automáticamente de la mortalidad. La esperanza bíblica necesitará una victoria mayor que la longevidad.", "Kol-yemei resume «todos los días de»."),
    v(9, "Enós engendra a Cainán", "Enós tiene noventa años cuando nace Cainán.", "וַיּוֹלֶד אֶת־קֵינָן", "Vayoled et-Qenan", "La promesa avanza mediante generaciones ordinarias. El texto valora la continuidad fiel más que hazañas individuales.", "Qenan se distingue de Qayin, aunque los nombres pueden sonar próximos."),
    v(10, "La casa de Enós crece", "Enós vive ochocientos quince años más y tiene hijos e hijas.", "בָּנִים וּבָנוֹת", "Banim uvanot", "La población se multiplica conforme a la bendición creadora, aun bajo la tensión de la muerte.", "La fórmula evita pretender que solo existió el hijo nombrado."),
    v(11, "Enós muere", "La vida total de Enós es de novecientos cinco años y muere.", "תְּשַׁע מֵאוֹת שָׁנָה", "Tesha meot shanah", "El estribillo impide idealizar el pasado antediluviano como inmortalidad. La sentencia alcanza a todos.", "La edad se expresa mediante unidades numéricas acumuladas en hebreo."),
    v(12, "Cainán engendra a Mahalaleel", "Cainán tiene setenta años cuando nace Mahalaleel.", "וַיּוֹלֶד אֶת־מַהֲלַלְאֵל", "Vayoled et-Mahalalel", "La línea de descendencia sigue preservada. El nombre introduce una posible confesión de alabanza a Dios.", "Mahalalel puede entenderse como «alabanza de Dios»."),
    v(13, "Los descendientes de Cainán", "Cainán vive ochocientos cuarenta años más y tiene hijos e hijas.", "וַיּוֹלֶד בָּנִים וּבָנוֹת", "Vayoled banim uvanot", "La repetición produce ritmo teológico: vida concedida, fecundidad y finalmente muerte.", "Yalad abarca engendrar o dar origen dentro de una genealogía."),
    v(14, "Cainán muere", "Cainán alcanza novecientos diez años y muere.", "וַיָּמֹת", "Vayamot", "Ninguna cifra modifica el desenlace. La mortalidad domina el horizonte hasta la interrupción de Enoc.", "El cierre idéntico une las generaciones en una condición común."),
    v(15, "Mahalaleel engendra a Jared", "Mahalaleel tiene sesenta y cinco años cuando nace Jared.", "וַיּוֹלֶד אֶת־יָרֶד", "Vayoled et-Yared", "La descendencia continúa sin comentario moral, preparando al lector para la figura singular de Enoc.", "Yered puede relacionarse con una raíz que significa «descender», aunque la etimología es incierta."),
    v(16, "La familia de Mahalaleel", "Mahalaleel vive ochocientos treinta años más y tiene hijos e hijas.", "שְׁלֹשִׁים וּשְׁמֹנֶה מֵאוֹת", "Sheloshim ushemoneh meot", "La precisión numérica presenta una cadena ordenada de memoria familiar y continuidad.", "El hebreo combina centenas y decenas sin nuestro orden numérico moderno."),
    v(17, "Mahalaleel muere", "Mahalaleel vive ochocientos noventa y cinco años y muere.", "חָמֵשׁ וְתִשְׁעִים שָׁנָה", "Jamesh vetishim shanah", "La alabanza sugerida por su nombre no elimina la muerte, pero la historia de la promesa sigue adelante.", "Vayamot conserva el mismo cierre genealógico."),
    v(18, "Jared engendra a Enoc", "Jared tiene ciento sesenta y dos años cuando nace Enoc.", "וַיּוֹלֶד אֶת־חֲנוֹךְ", "Vayoled et-Janokh", "La narración llega al séptimo desde Adán por la línea de Seth, cuya vida romperá el patrón repetido.", "Janokh puede relacionarse con «dedicar» o «iniciar»."),
    v(19, "Los años posteriores de Jared", "Jared vive ochocientos años más y tiene hijos e hijas.", "שְׁמֹנֶה מֵאוֹת שָׁנָה", "Shemoneh meot shanah", "La continuidad familiar rodea la historia particular de Enoc y sitúa su experiencia dentro de una genealogía real.", "La fórmula mantiene el ritmo antes del cambio narrativo."),
    v(20, "Jared muere", "Jared alcanza novecientos sesenta y dos años y muere.", "שְׁתַּיִם וְשִׁשִּׁים שָׁנָה", "Shtayim veshishim shanah", "Su vida es una de las más largas registradas, pero comparte el desenlace adámico.", "Las edades antediluvianas deben recibirse según la intención genealógica del texto, evitando cálculos que este no exige."),
    v(21, "Enoc engendra a Matusalén", "Enoc tiene sesenta y cinco años cuando nace Matusalén.", "וַיּוֹלֶד אֶת־מְתוּשָׁלַח", "Vayoled et-Metushalaj", "El nacimiento introduce el período durante el cual se describirá la comunión sostenida de Enoc con Dios.", "Metushalaj es Matusalén; su etimología exacta es discutida."),
    v(22, "Enoc camina con Dios", "Después de Matusalén, Enoc camina con Dios trescientos años y tiene hijos e hijas.", "וַיִּתְהַלֵּךְ חֲנוֹךְ אֶת־הָאֱלֹהִים", "Vayithallekh Janokh et-haElohim", "Caminar con Dios describe relación perseverante, no una experiencia momentánea. Vida familiar y comunión divina aparecen juntas.", "Hithallekh es una forma intensiva o reflexiva de halakh, «andar»."),
    v(23, "La vida de Enoc", "Todos los días de Enoc suman trescientos sesenta y cinco años.", "שָׁלֹשׁ מֵאוֹת שָׁנָה וְשִׁשִּׁים וְחָמֵשׁ", "Shalosh meot shanah veshishim vejamesh", "Su edad es mucho menor que las de alrededor, pero el valor de su vida se define por caminar con Dios, no por duración.", "La cifra total prepara la ausencia deliberada de «y murió»."),
    v(24, "Dios toma a Enoc", "Enoc camina con Dios y deja de estar presente porque Dios lo toma.", "וְאֵינֶנּוּ כִּי־לָקַח אֹתוֹ אֱלֹהִים", "Veeinennu ki-laqaj oto Elohim", "La fórmula de muerte es reemplazada por una acción divina. Hebreos interpreta que Enoc fue trasladado para no ver muerte, anticipando esperanza más allá de la sentencia.", "Einennu significa «ya no estaba». Laqaj, «tomó», puede describir recepción divina."),
    v(25, "Matusalén engendra a Lamec", "Matusalén tiene ciento ochenta y siete años cuando nace Lamec.", "וַיּוֹלֶד אֶת־לָמֶךְ", "Vayoled et-Lemekh", "Este Lamec pertenece a la línea de Seth y debe distinguirse del descendiente violento de Caín.", "La repetición del nombre no implica identidad; las genealogías siguen líneas diferentes."),
    v(26, "La casa de Matusalén", "Matusalén vive setecientos ochenta y dos años más y tiene hijos e hijas.", "שְׁתַּיִם וּשְׁמוֹנִים שָׁנָה", "Shtayim ushemonim shanah", "La generación se prolonga hasta las cercanías del diluvio, enlazando el mundo de Adán con el de Noé.", "La cronología literaria conecta las generaciones sin narrar todos sus acontecimientos."),
    v(27, "Matusalén muere", "Matusalén alcanza novecientos sesenta y nueve años y muere.", "תֵּשַׁע וְשִׁשִּׁים שָׁנָה", "Tesha veshishim shanah", "Es la mayor edad registrada en la Biblia, pero el estribillo de muerte permanece. La longevidad no equivale a vida eterna.", "Vayamot vuelve después de la excepción de Enoc."),
    v(28, "Lamec engendra un hijo", "Lamec tiene ciento ochenta y dos años cuando nace un hijo.", "וַיּוֹלֶד בֵּן", "Vayoled ben", "El narrador retrasa el nombre para destacar la explicación profética que sigue. La familia espera alivio en una tierra fatigosa.", "Ben, «hijo», queda sin nombre hasta la declaración paterna."),
    v(29, "Noé y la esperanza de consuelo", "Lamec llama Noé a su hijo esperando consuelo del trabajo penoso causado por la tierra maldita.", "זֶה יְנַחֲמֵנוּ", "Zeh yenajamenu", "La esperanza interpreta a Noé dentro del problema de Génesis 3. Él traerá preservación y un nuevo comienzo, aunque no eliminará definitivamente el pecado.", "Noaj se asocia aquí con najam, «consolar», mediante un juego de sonido más que una etimología exacta."),
    v(30, "Los años posteriores de Lamec", "Lamec vive quinientos noventa y cinco años más y tiene hijos e hijas.", "חָמֵשׁ וְתִשְׁעִים שָׁנָה", "Jamesh vetishim shanah", "La familia se amplía mientras se acerca la crisis descrita en el capítulo siguiente.", "La fórmula habitual mantiene a Noé dentro de la línea genealógica."),
    v(31, "Lamec muere", "Lamec vive setecientos setenta y siete años y muere.", "שֶׁבַע וְשִׁבְעִים שָׁנָה", "Sheva veshivim shanah", "La cifra de sietes contrasta literariamente con el Lamec de 4:24: aquí la esperanza se expresa en consuelo, no en venganza.", "La repetición de siete puede aportar una resonancia de plenitud sin anular el dato genealógico."),
    v(32, "Los tres hijos de Noé", "A los quinientos años, Noé engendra a Sem, Cam y Jafet.", "וַיּוֹלֶד נֹחַ אֶת־שֵׁם אֶת־חָם וְאֶת־יָפֶת", "Vayoled Noaj et-Shem et-Jam veet-Yafet", "Los tres hijos forman el puente hacia el diluvio y la repoblación posterior. El orden puede reflejar importancia narrativa más que edad estricta.", "Shem, Jam y Yefet serán cabezas de las familias descritas en Génesis 10."),
  ],
  [
    { title: "La imagen divina continúa", text: "La caída hiere la humanidad, pero no elimina la dignidad otorgada por Dios." },
    { title: "La muerte reina", text: "El estribillo «y murió» confirma la gravedad histórica del pecado." },
    { title: "La promesa avanza por generaciones", text: "Dios preserva una línea que conduce de Adán a Noé y finalmente al Mesías." },
    { title: "Caminar con Dios abre esperanza", text: "Enoc anticipa que la comunión divina tiene una palabra más fuerte que la muerte." },
  ],
  "Las edades de Génesis 5 han producido diversos modelos cronológicos. El propósito evidente del capítulo es conectar a Adán con Noé y mostrar simultáneamente fecundidad y muerte. No conviene convertir la genealogía por sí sola en una fecha absoluta de la creación sin considerar convenciones genealógicas antiguas.",
  [
    ["1 Crónicas 1:1–4", "La historia de Israel se sitúa dentro de la misma línea desde Adán hasta Noé."],
    ["Lucas 3:36–38", "La genealogía de Jesús remonta su línea hasta Adán y Dios."],
    ["Hebreos 11:5–6", "Enoc es presentado como ejemplo de fe que agrada a Dios."],
    ["Judas 14–15", "La tradición sobre Enoc es usada para anunciar juicio contra la impiedad."],
  ],
);

const genesis6 = c(
  6,
  "Corrupción, juicio y gracia",
  "Génesis 6 lleva la violencia humana a su punto crítico y presenta el diluvio como juicio moral, no como accidente natural. En contraste con una tierra corrompida, Noé recibe gracia, camina con Dios y obedece la orden de construir el arca.",
  [
    v(1, "La humanidad se multiplica", "La población aumenta sobre la tierra y nacen hijas.", "כִּי־הֵחֵל הָאָדָם לָרֹב", "Ki-hejel haadam larov", "La bendición de multiplicarse continúa, pero el crecimiento numérico no equivale a fidelidad. El versículo prepara una nueva expresión del desorden humano.", "Larov procede de rav, «ser numeroso»; benot significa «hijas»."),
    v(2, "Uniones gobernadas por el deseo", "Los hijos de Dios ven que las hijas de los hombres son hermosas y toman las mujeres que eligen.", "וַיִּקְחוּ לָהֶם נָשִׁים", "Vayiqju lahem nashim", "La identidad de los «hijos de Dios» se ha interpretado como seres celestiales, gobernantes o una línea humana. En todas las lecturas, el énfasis narrativo cae en tomar según el propio deseo, eco de Génesis 3:6.", "Bene-haElohim es una expresión discutida. Mi-kol asher bajaru, «de todas las que escogieron», subraya elección sin límite declarado."),
    v(3, "El límite divino", "Dios declara que su Espíritu no contenderá indefinidamente con el ser humano y fija ciento veinte años.", "לֹא־יָדוֹן רוּחִי בָאָדָם", "Lo-yadon ruji vaadam", "Dios limita la prolongación de una humanidad mortal y rebelde. Los ciento veinte años pueden indicar el plazo antes del diluvio o un límite de longevidad; el contexto admite debate, pero la paciencia divina no es infinita.", "Yadon es raro y puede significar «contender», «permanecer» o «gobernar». Besaggam hu basar recalca que el humano es carne."),
    v(4, "Los poderosos de la antigüedad", "Los nefilim están en la tierra en aquellos días; de estas uniones surgen guerreros famosos.", "הַנְּפִלִים הָיוּ בָאָרֶץ", "Hannefilim hayu vaarets", "El texto describe figuras temibles del mundo antiguo sin convertirlas en héroes de fe. Su fama no corrige la valoración divina de la generación.", "Nefilim tiene etimología incierta y no debe traducirse automáticamente «gigantes». Gibborim son «poderosos» o «guerreros»."),
    v(5, "El mal alcanza el corazón", "Dios ve que la maldad humana es grande y que la orientación de sus pensamientos es continuamente mala.", "כָּל־יֵצֶר מַחְשְׁבֹת לִבּוֹ", "Kol-yetser majshevot libbo", "La evaluación penetra acciones, imaginación y voluntad. No afirma que cada conducta tenga igual gravedad, sino que la dirección interior de la sociedad se ha vuelto persistentemente contra Dios.", "Yetser es «formación» o «inclinación»; lev en hebreo incluye pensamiento, voluntad y afectos."),
    v(6, "El dolor de Dios", "Dios lamenta haber hecho al ser humano y se aflige en su corazón.", "וַיִּתְעַצֵּב אֶל־לִבּוֹ", "Vayyitatsev el-libbo", "El lenguaje relacional expresa dolor real ante el pecado, no ignorancia ni error moral en Dios. La Escritura habla de su respuesta en términos comprensibles sin negar su conocimiento soberano.", "Najam puede expresar pesar o cambio de disposición; atsav comunica profundo dolor."),
    v(7, "Sentencia sobre la creación", "Dios anuncia que borrará a seres humanos y animales de la superficie terrestre.", "אֶמְחֶה אֶת־הָאָדָם", "Emjeh et-haadam", "El dominio humano hace que su rebelión arrastre al mundo viviente bajo juicio. La amplitud de la sentencia muestra que el pecado nunca es meramente privado.", "Majah significa «borrar» o «eliminar». La lista recorre humanidad, ganado, reptiles y aves."),
    v(8, "Noé encuentra gracia", "Noé recibe favor ante los ojos del Señor.", "וְנֹחַ מָצָא חֵן", "Venoaj matsa jen", "La gracia precede a la obediencia que será descrita. Noé no se salva por pertenecer a una humanidad superior, sino porque Dios le concede favor y lo llama.", "Jen es «favor» o «gracia». El juego sonoro entre Noaj y jen marca el giro del relato."),
    v(9, "Justo y caminando con Dios", "Noé es presentado como justo, íntegro entre sus contemporáneos y caminando con Dios.", "צַדִּיק תָּמִים", "Tsaddiq tamim", "Su justicia describe fidelidad concreta dentro de una generación corrupta; no impecabilidad absoluta. Como Enoc, su vida se define por comunión con Dios.", "Tsaddiq significa «justo»; tamim, «íntegro» o «completo», puede expresar una vida sin doblez."),
    v(10, "Los hijos de Noé", "Noé engendra a Sem, Cam y Jafet.", "אֶת־שֵׁם אֶת־חָם וְאֶת־יָפֶת", "Et-Shem et-Jam veet-Yafet", "La familia elegida para sobrevivir enlaza la genealogía anterior con la repoblación posterior. Los hijos participarán tanto de la liberación como de sus responsabilidades.", "El orden de los nombres sigue su función narrativa y no demuestra por sí solo el orden de nacimiento."),
    v(11, "Una tierra llena de violencia", "La tierra se corrompe delante de Dios y queda llena de violencia.", "וַתִּמָּלֵא הָאָרֶץ חָמָס", "Vattimmale haarets jamas", "La violencia es la manifestación social de la corrupción interior. «Delante de Dios» afirma que ninguna normalización cultural elimina su evaluación moral.", "Shajat es «corromper» o «arruinar»; jamas incluye violencia, injusticia y atropello."),
    v(12, "Toda conducta corrompida", "Dios observa la tierra y ve que toda carne ha corrompido su camino.", "הִשְׁחִית כָּל־בָּשָׂר אֶת־דַּרְכּוֹ", "Hishjit kol-basar et-darko", "El diagnóstico es comprobado por Dios y abarca la vida colectiva. El «camino» señala patrones escogidos, no solo debilidad pasiva.", "Derekh puede significar senda o manera de vivir. Kol-basar, «toda carne», recalca universalidad."),
    v(13, "El fin anunciado", "Dios comunica a Noé que pondrá fin a toda carne porque la tierra está llena de violencia.", "קֵץ כָּל־בָּשָׂר בָּא לְפָנַי", "Qets kol-basar ba lefanai", "Antes de ejecutar juicio, Dios revela su propósito y prepara preservación. La causa moral se repite: violencia humana y destrucción divina no son equivalentes arbitrarios.", "Qets es «fin». La frase ba lefanai puede expresar que la decisión ha llegado ante Dios."),
    v(14, "Construye un arca", "Dios ordena hacer un arca de madera, con compartimentos y revestimiento interior y exterior.", "עֲשֵׂה לְךָ תֵּבַת עֲצֵי־גֹפֶר", "Aseh lekha tevat atse-gofer", "La salvación incluye un mandato concreto que exige confianza prolongada. El arca no se diseña para navegar hacia un destino humano, sino para ser sostenida por Dios en medio del juicio.", "Tevah, «arca», aparece también para la cesta de Moisés. Gofer designa una madera no identificada con certeza; kofer es el revestimiento."),
    v(15, "Dimensiones para preservar vida", "El arca debe medir trescientos codos de largo, cincuenta de ancho y treinta de alto.", "שְׁלֹשׁ מֵאוֹת אַמָּה", "Shelosh meot ammah", "Las dimensiones concretas anclan la obediencia en una tarea material y ofrecen una proporción estable para la gran embarcación.", "Ammah es «codo», medida basada en el antebrazo y variable en la antigüedad; no permite una conversión moderna absolutamente exacta."),
    v(16, "Luz, puerta y tres niveles", "Dios prescribe una abertura superior, una puerta lateral y tres cubiertas.", "תַּחְתִּיִּם שְׁנִיִּם וּשְׁלִשִׁים", "Tajtiyyim sheniyyim ushelishim", "La instrucción combina protección, acceso y organización. La provisión divina no elimina el uso cuidadoso de medios y estructura.", "Tsohar puede ser ventana, abertura o cubierta; su significado exacto es debatido. Los niveles son inferior, segundo y tercero."),
    v(17, "El diluvio vendrá", "Dios traerá aguas para destruir bajo el cielo a todo ser terrestre con aliento de vida.", "הַמַּבּוּל מַיִם עַל־הָאָרֶץ", "Hammabbul mayim al-haarets", "Dios se identifica como juez y soberano de las aguas. El lenguaje invierte la separación creadora de Génesis 1 y presenta el diluvio como una des-creación judicial.", "Mabbul es el término especial para el diluvio de Noé. Ruaj jayyim es «aliento» o «espíritu de vida»."),
    v(18, "La primera mención del pacto", "Dios establecerá su pacto con Noé, quien entrará al arca con su esposa, hijos y nueras.", "וַהֲקִמֹתִי אֶת־בְּרִיתִי אִתָּךְ", "Vahaqimoti et-beriti ittakh", "La preservación descansa en el compromiso iniciado por Dios. La familia es incluida con Noé y se convierte en núcleo de un nuevo comienzo humano.", "Berit es «pacto». Haqim, «establecer» o «confirmar», presenta a Dios como garante."),
    v(19, "Representantes de los animales", "Noé debe introducir parejas de cada clase de ser viviente para conservarlas.", "לְהַחֲיֹת אִתָּךְ", "Lehajayot ittakh", "La misión humana de cuidar criaturas continúa dentro del juicio. Dios preserva diversidad de vida y asigna a Noé participación responsable.", "Lehajayot significa «mantener con vida». Min, «especie» o «clase», no corresponde necesariamente a la taxonomía moderna."),
    v(20, "Vendrán según su clase", "Aves, animales y seres que se arrastran vendrán a Noé de dos en dos para vivir.", "שְׁנַיִם מִכֹּל יָבֹאוּ אֵלֶיךָ", "Shenayim mikkol yavo elekha", "Dios dirige la llegada de los animales; Noé recibe una tarea imposible de reducir a control humano autónomo.", "Yavo, «vendrán», tiene a los animales como sujeto y destaca iniciativa providencial."),
    v(21, "Alimento almacenado", "Noé debe reunir comida para su familia y los animales.", "וְאָסַפְתָּ אֵלֶיךָ", "Veasafta elekha", "La confianza no es pasividad: la promesa de preservación incorpora planificación, trabajo y provisión ordinaria.", "Asaf significa «recoger» o «almacenar». Maakal abarca alimento para humanos y animales."),
    v(22, "Obediencia completa", "Noé hace todo exactamente como Dios le ordena.", "כְּכֹל אֲשֶׁר צִוָּה אֹתוֹ", "Kekhol asher tsivvah oto", "La respuesta concluye la sección con obediencia integral. En una generación que corrompió su camino, Noé ordena su conducta por la palabra divina.", "Ken asah, «así hizo», unido a kekhol, «conforme a todo», enfatiza correspondencia entre mandato y acción."),
  ],
  [
    { title: "Dios juzga el mal real", text: "El diluvio responde a corrupción y violencia persistentes, no a capricho divino." },
    { title: "La gracia inicia la salvación", text: "Noé encuentra favor antes de que el relato destaque su obediencia." },
    { title: "El pacto preserva", text: "Dios compromete su palabra con una familia y con la continuidad de la vida." },
    { title: "La fe obedece", text: "La confianza de Noé toma forma en construcción, preparación y perseverancia." },
  ],
  "La identidad de los «hijos de Dios», los nefilim y el sentido exacto de los ciento veinte años admiten interpretaciones responsables diferentes. Estas cuestiones no deben desplazar el mensaje claro del capítulo: la violencia humana provoca juicio, mientras la gracia de Dios abre un camino de preservación.",
  [
    ["Mateo 24:37–39", "Jesús usa los días de Noé para llamar a vigilancia ante el juicio venidero."],
    ["Hebreos 11:7", "La construcción del arca es interpretada como respuesta de fe a la advertencia divina."],
    ["1 Pedro 3:18–22", "La preservación a través del agua se relaciona tipológicamente con salvación y bautismo."],
    ["2 Pedro 2:5", "Noé aparece como pregonero de justicia en medio de un mundo impío."],
  ],
);

const genesis7 = c(
  7,
  "El juicio de las aguas",
  "Génesis 7 narra la entrada al arca y la llegada del diluvio mediante una cronología solemne. La repetición de la obediencia de Noé, el cierre divino de la puerta y la extensión de las aguas muestran simultáneamente refugio para los llamados y juicio sobre la violencia del mundo.",
  [
    v(1, "Entra en el arca", "Dios llama a Noé y a su familia a entrar porque lo ha visto justo en su generación.", "בֹּא־אַתָּה וְכָל־בֵּיתְךָ", "Bo-attah vekhol-betekha", "La justicia observada no reemplaza la gracia de 6:8; muestra su fruto. La invitación de Dios convierte el arca preparada en refugio efectivo.", "Bo significa «ven» o «entra»; la formulación puede sugerir la presencia acogedora de Dios. Bayit incluye la casa familiar."),
    v(2, "Animales limpios y no limpios", "Noé debe tomar siete pares de animales limpios y un par de los no limpios.", "מִכֹּל הַבְּהֵמָה הַטְּהוֹרָה", "Mikkol habbehemah hattehorah", "La distinción anticipa el sacrificio posterior y demuestra categorías cultuales conocidas antes de Sinaí. La cantidad adicional preserva la especie aun después de la ofrenda.", "Tahor significa «limpio»; lo tehorah, «no limpio». La sintaxis numérica admite discusión entre siete animales o siete pares; el contexto favorece abundancia."),
    v(3, "Aves preservadas", "También se llevan siete pares de aves para conservar descendencia sobre la tierra.", "לְחַיּוֹת זֶרַע", "Lejayyot zera", "La finalidad explícita es preservar descendencia. El juicio no abandona el propósito creador de llenar la tierra con vida.", "Zera es «semilla» o «descendencia»; aquí se aplica a continuidad animal."),
    v(4, "Siete días de advertencia", "Después de siete días lloverá cuarenta días y noches, y Dios borrará a los seres vivientes.", "לְיָמִים עוֹד שִׁבְעָה", "Leyamim od shivah", "El plazo final une paciencia y certeza. Los cuarenta días forman un período completo de prueba y juicio en la memoria bíblica.", "Mamtir es «hacer llover». Mejiti retoma majah, «borrar», de 6:7."),
    v(5, "Noé vuelve a obedecer", "Noé cumple todo lo que el Señor le manda.", "כְּכֹל אֲשֶׁר־צִוָּהוּ יְהוָה", "Kekhol asher-tsivvahu Adonai", "La repetición no es redundante: subraya obediencia sostenida cuando la advertencia está a punto de hacerse visible.", "El nombre del pacto, YHWH, acompaña aquí el mandato y la fidelidad relacional."),
    v(6, "Seiscientos años", "Noé tiene seiscientos años cuando llegan las aguas del diluvio.", "בֶּן־שֵׁשׁ מֵאוֹת שָׁנָה", "Ben-shesh meot shanah", "La edad enlaza la narración con la genealogía y sitúa el acontecimiento en la vida concreta de Noé.", "Ben seguido de una cifra es el modismo hebreo para indicar edad."),
    v(7, "La familia entra", "Noé, su esposa, sus hijos y sus nueras entran al arca a causa de las aguas.", "מִפְּנֵי מֵי הַמַּבּוּל", "Mippene me hammabbul", "La familia responde junta a la advertencia. El refugio es provisto por Dios, pero debe ser recibido entrando.", "Mippene puede significar «a causa de» o «ante la presencia de»."),
    v(8, "Toda categoría representada", "Entran animales limpios, no limpios, aves y los que se arrastran.", "וְכֹל אֲשֶׁר־רֹמֵשׂ", "Vekhol asher-romesh", "El catálogo recuerda Génesis 1 y confirma que la preservación alcanza las distintas esferas de vida terrestre.", "Remes designa seres que se desplazan cerca del suelo."),
    v(9, "De dos en dos", "Macho y hembra llegan a Noé y entran como Dios había ordenado.", "שְׁנַיִם שְׁנַיִם", "Shenayim shenayim", "La repetición representa parejas ordenadas para continuidad. La llegada cumple la promesa de 6:20 y acompaña la obediencia humana con providencia divina.", "La duplicación hebrea significa «de dos en dos». Zakhar uneqevah son «macho y hembra»."),
    v(10, "La espera se cumple", "Al terminar los siete días, las aguas del diluvio llegan sobre la tierra.", "וַיְהִי לְשִׁבְעַת הַיָּמִים", "Vayehi leshivat hayyamim", "El anuncio se cumple en el tiempo señalado. La demora no fue cancelación, y la exactitud afirma la confiabilidad de la palabra divina.", "Vayehi marca transición narrativa: «y sucedió»."),
    v(11, "Las fuentes y las compuertas", "En una fecha precisa se rompen las fuentes del gran abismo y se abren las compuertas del cielo.", "נִבְקְעוּ כָּל־מַעְיְנֹת תְּהוֹם רַבָּה", "Nivqeu kol-mayenot tehom rabbah", "Las aguas contenidas en la creación irrumpen desde abajo y arriba. La descripción evoca una inversión cósmica del orden de Génesis 1.", "Tehom es «abismo»; arubbot hashamayim son «compuertas del cielo», lenguaje fenomenológico de precipitación desbordada."),
    v(12, "Cuarenta días y noches", "La lluvia cae sobre la tierra durante cuarenta días y cuarenta noches.", "אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה", "Arbaim yom vearbaim laylah", "La duración sostenida demuestra que no se trata de una tormenta pasajera. El número cuarenta reaparecerá en períodos bíblicos de prueba y transición.", "Geshem suele indicar lluvia intensa; la pareja día/noche expresa continuidad."),
    v(13, "El mismo día", "Ese mismo día entran Noé, su familia y sus tres hijos al arca.", "בְּעֶצֶם הַיּוֹם הַזֶּה", "Beetsem hayyom hazzeh", "La fórmula recalca cumplimiento puntual y unidad familiar. Los nombres conectan a los sobrevivientes con las naciones futuras.", "Beetsem hayyom significa «en ese mismo día» y aporta precisión solemne."),
    v(14, "La creación entra por clases", "Con ellos entran bestias, ganado, reptiles y aves según sus clases.", "לְמִינָהּ", "Leminah", "El lenguaje de «según su clase» retoma la creación ordenada. El arca funciona como espacio de conservación del mundo viviente.", "Min y sus formas no equivalen exactamente a «especie» científica; señalan agrupaciones reconocibles del texto."),
    v(15, "Aliento de vida", "Los animales con aliento de vida llegan de dos en dos al arca.", "רוּחַ חַיִּים", "Ruaj jayyim", "Lo que Dios insufló y sostuvo en la creación queda ahora bajo su protección dentro del arca.", "Ruaj puede ser viento, aliento o espíritu; aquí identifica la vida respirante."),
    v(16, "El Señor cierra", "Entran macho y hembra como Dios ordenó, y el Señor cierra la puerta detrás de Noé.", "וַיִּסְגֹּר יְהוָה בַּעֲדוֹ", "Vayyisgor Adonai baado", "El gesto final de seguridad pertenece a Dios. La misma puerta que guarda a los de dentro marca el término de la oportunidad para los de fuera.", "Sagar significa «cerrar». Baado puede significar «tras él» o «en torno de él»."),
    v(17, "El arca es levantada", "Durante cuarenta días las aguas crecen y elevan el arca sobre la tierra.", "וַתָּרָם מֵעַל הָאָרֶץ", "Vattaram meal haarets", "Las aguas que destruyen el viejo mundo sostienen el medio de salvación ordenado por Dios. Juicio y preservación ocurren en el mismo acontecimiento.", "Rum significa «levantarse»; el arca pasa de reposar en tierra a flotar."),
    v(18, "Las aguas prevalecen", "Las aguas aumentan poderosamente mientras el arca flota sobre ellas.", "וַיִּגְבְּרוּ הַמַּיִם", "Vayigberu hammayim", "El relato acumula verbos de crecimiento para comunicar dominio total de las aguas; el arca permanece porque Dios cumple su palabra.", "Gavar significa «ser fuerte» o «prevalecer». Halakh puede describir aquí el desplazamiento del arca."),
    v(19, "Los montes cubiertos", "Las aguas prevalecen hasta cubrir todos los montes altos bajo el cielo.", "וַיְכֻסּוּ כָּל־הֶהָרִים הַגְּבֹהִים", "Vayekhussu kol-heharim haggevohim", "La perspectiva del narrador es total y deliberada: ninguna altura ofrece un refugio alternativo al que Dios había provisto.", "Kasah significa «cubrir». La repetición de kol, «todo», domina la descripción."),
    v(20, "Quince codos por encima", "Las aguas suben quince codos por encima y los montes quedan cubiertos.", "חֲמֵשׁ עֶשְׂרֵה אַמָּה", "Jamesh esreh ammah", "La medida confirma profundidad suficiente para la flotación y refuerza la imagen de completa cobertura presentada por el relato.", "La relación exacta entre esta cifra y el calado del arca no se explica; el texto resalta suficiencia."),
    v(21, "Muere toda carne terrestre", "Perecen aves, animales, seres que se desplazan y toda la humanidad fuera del arca.", "וַיִּגְוַע כָּל־בָּשָׂר", "Vayigva kol-basar", "El orden de criaturas de Génesis 1 aparece en dirección de muerte. La gravedad del juicio corresponde a una tierra que toda carne había corrompido.", "Gava significa «expirar» o «morir». Kol-basar abarca aquí vida terrestre respirante."),
    v(22, "El aliento se extingue", "Todo lo que tenía aliento de espíritu de vida en tierra seca muere.", "נִשְׁמַת־רוּחַ חַיִּים", "Nishmat-ruaj jayyim", "La vida que depende del aliento divino no puede sostenerse autónomamente. La especificación de tierra seca distingue a los habitantes terrestres.", "Neshamah es «aliento»; bejaravah significa «en terreno seco»."),
    v(23, "Solo queda Noé", "Dios borra a los seres de la superficie; permanecen Noé y quienes están con él en el arca.", "וַיִשָּׁאֶר אַךְ־נֹחַ", "Vayyishaer akh-Noaj", "La frase concentra el contraste entre juicio universal y remanente preservado. Noé no queda solo: la comunidad del arca comparte la salvación.", "Akh tiene fuerza restrictiva: «solamente». Shaar significa «quedar» o «sobrevivir»."),
    v(24, "Ciento cincuenta días", "Las aguas prevalecen sobre la tierra durante ciento cincuenta días.", "חֲמִשִּׁים וּמְאַת יוֹם", "Jamishim umeat yom", "El capítulo cierra en suspensión: el juicio se prolonga y los sobrevivientes dependen por completo de que Dios recuerde su pacto.", "La cifra enlaza con 8:3 y abarca un período mayor que los cuarenta días de lluvia."),
  ],
  [
    { title: "La palabra de Dios se cumple", text: "El plazo, la entrada y la llegada de las aguas ocurren como habían sido anunciados." },
    { title: "Dios mismo asegura el refugio", text: "Noé construye y entra; el Señor es quien cierra la puerta." },
    { title: "El juicio deshace un mundo violento", text: "Las aguas invierten el orden creado y muestran la seriedad del pecado." },
    { title: "Dios conserva un remanente", text: "La familia y los animales preservados llevan consigo la posibilidad de un nuevo comienzo." },
  ],
  "El alcance geográfico y los mecanismos físicos del diluvio han generado modelos distintos entre intérpretes. El texto bíblico centra su atención en el significado teológico: el mundo conocido queda bajo juicio, no existe refugio humano alternativo y Dios preserva fielmente a quienes llamó al arca.",
  [
    ["Isaías 54:9–10", "Las aguas de Noé se convierten en garantía de la compasión pactal de Dios."],
    ["Mateo 24:38–39", "Jesús destaca la vida despreocupada que continuó hasta que llegó el diluvio."],
    ["Hebreos 11:7", "Noé condena al mundo y hereda justicia al responder con fe."],
    ["2 Pedro 3:5–7", "El diluvio fundamenta la certeza de un juicio futuro por la palabra de Dios."],
  ],
);

const genesis8 = c(
  8,
  "Dios recuerda y renueva",
  "Génesis 8 cambia el movimiento del relato: las aguas dejan de prevalecer porque Dios recuerda a Noé y a las criaturas. La salida paciente, el altar y la promesa sobre los ciclos de la tierra presentan una nueva creación sostenida por gracia.",
  [
    v(1, "Dios recuerda a Noé", "Dios recuerda a Noé y a los animales, hace pasar un viento y las aguas comienzan a bajar.", "וַיִּזְכֹּר אֱלֹהִים אֶת־נֹחַ", "Vayyizkor Elohim et-Noaj", "Recordar no implica olvido previo; en lenguaje pactal significa actuar fielmente a favor de alguien. El viento sobre las aguas evoca Génesis 1:2 e inicia la re-creación.", "Zakhar es «recordar con acción». Ruaj significa viento, aliento o espíritu; aquí el efecto sobre las aguas favorece «viento»."),
    v(2, "Las aguas son contenidas", "Se cierran las fuentes del abismo y las compuertas del cielo, y la lluvia se detiene.", "וַיִּסָּכְרוּ מַעְיְנֹת תְּהוֹם", "Vayyissakhru mayenot tehom", "Dios vuelve a contener las aguas que habían irrumpido en 7:11. El mismo soberano que juzga establece el límite del juicio.", "Sakhar es «cerrar» o «represar»; kala comunica que la lluvia fue retenida."),
    v(3, "Retroceso gradual", "Las aguas se retiran continuamente y disminuyen al cabo de ciento cincuenta días.", "וַיָּשֻׁבוּ הַמַּיִם", "Vayyashuvu hammayim", "La liberación ocurre como proceso gobernado, no siempre como cambio instantáneo. La cifra cierra el período iniciado en 7:24.", "Shuv, «volver», aparece con una construcción intensiva: las aguas iban retirándose."),
    v(4, "Reposo sobre Ararat", "El día diecisiete del séptimo mes el arca reposa sobre los montes de Ararat.", "וַתָּנַח הַתֵּבָה", "Vattanaj hattevah", "El reposo del arca realiza un juego con el nombre de Noé y señala estabilidad después del caos. «Montes de Ararat» designa una región, no identifica necesariamente una cumbre moderna.", "Nuaj significa «reposar» y resuena con Noaj. Ararat corresponde al territorio antiguo de Urartu."),
    v(5, "Aparecen las cumbres", "Las aguas siguen bajando y el primer día del décimo mes se ven las cimas de los montes.", "נִרְאוּ רָאשֵׁי הֶהָרִים", "Niru rashe heharim", "La tierra emerge gradualmente como en la separación de tierra y aguas de Génesis 1. La visibilidad no significa todavía que el suelo sea habitable.", "Niru es «fueron vistas»; rashe, literalmente «cabezas», significa cumbres."),
    v(6, "Noé abre la ventana", "Después de cuarenta días Noé abre la ventana que había construido.", "וַיִּפְתַּח נֹחַ אֶת־חַלּוֹן הַתֵּבָה", "Vayyiftaj Noaj et-jallon hattevah", "Noé observa responsablemente las condiciones sin adelantarse a la orden divina de salir. Fe y evaluación concreta cooperan.", "Jallon es una ventana o abertura, distinta posiblemente del tsohar de 6:16."),
    v(7, "El cuervo explora", "Noé envía un cuervo que va y vuelve hasta que las aguas se secan.", "וַיְשַׁלַּח אֶת־הָעֹרֵב", "Vayeshalaj et-haorev", "El ave resistente puede mantenerse fuera mediante vuelos sucesivos. Su conducta ofrece información parcial, pero no una señal suficiente para salir.", "Yatso vashov, «saliendo y volviendo», expresa movimiento repetido."),
    v(8, "La paloma es enviada", "Noé envía una paloma para saber si las aguas han bajado de la superficie.", "לִרְאוֹת הֲקַלּוּ הַמַּיִם", "Lirot haqallu hammayim", "La búsqueda de suelo disponible refleja paciencia práctica. La paloma, más dependiente de tierra firme, sirve como mejor indicador.", "Qalal significa «ser ligero» o «disminuir»; la pregunta investiga si las aguas se han aliviado."),
    v(9, "Sin lugar para reposar", "La paloma no encuentra dónde apoyar la pata y regresa; Noé la recibe en el arca.", "וְלֹא־מָצְאָה הַיּוֹנָה מָנוֹחַ", "Velo-matseah hayyonah manoaj", "Aunque las cumbres eran visibles, la tierra aún no sostenía vida normal. La mano extendida de Noé muestra cuidado por la criatura bajo su responsabilidad.", "Manoaj es «lugar de reposo» y vuelve a resonar con Noé. Kaf-reglah es la planta de su pie."),
    v(10, "Siete días más", "Noé espera otros siete días y vuelve a enviar la paloma.", "וַיָּחֶל עוֹד שִׁבְעַת יָמִים", "Vayyajel od shivat yamim", "La espera disciplinada evita confundir una señal incompleta con permiso divino. El ritmo semanal estructura la observación.", "La raíz de vayajel es discutida, pero en contexto comunica esperar pacientemente."),
    v(11, "Una hoja de olivo", "Al atardecer la paloma vuelve con una hoja fresca de olivo, y Noé sabe que las aguas disminuyeron.", "עֲלֵה־זַיִת טָרָף בְּפִיהָ", "Aleh-zayit taraf befiha", "La hoja confirma vegetación accesible y se vuelve señal de vida renovada. El texto no exige que simbolice por sí sola una paz abstracta; comunica evidencia de restauración.", "Taraf puede significar «recién arrancada». Zayit es olivo; befiha, «en su pico»."),
    v(12, "La paloma no regresa", "Tras esperar otros siete días, Noé envía la paloma y esta ya no vuelve.", "וְלֹא־יָסְפָה שׁוּב־אֵלָיו", "Velo-yasfah shuv-elav", "La ausencia indica que la tierra ya puede sostener al ave. Noé recibe confirmación, aunque todavía no abandona el arca por iniciativa propia.", "Yasaf con infinitivo significa «volver a» hacer algo; aquí, no regresó más."),
    v(13, "La superficie se seca", "En el año seiscientos uno de Noé, él retira la cubierta y ve seca la superficie del suelo.", "חָרְבוּ הַמַּיִם", "Jarevu hammayim", "Noé obtiene evidencia visual directa. Sin embargo, el versículo siguiente distingue superficie seca de tierra completamente firme, enseñando paciencia ante etapas de recuperación.", "Jarav significa «secarse». Mikhseh es cubierta; pene haadamah, «superficie del suelo»."),
    v(14, "La tierra queda firme", "El día veintisiete del segundo mes la tierra está completamente seca.", "יָבְשָׁה הָאָרֶץ", "Yaveshah haarets", "La cronología marca una permanencia extensa en el arca. La salvación incluye esperar hasta que el entorno sea verdaderamente habitable.", "Yabesh señala sequedad firme y contrasta con jarav del versículo anterior."),
    v(15, "Dios vuelve a hablar", "Dios dirige su palabra a Noé.", "וַיְדַבֵּר אֱלֹהִים אֶל־נֹחַ", "Vayedabber Elohim el-Noaj", "La salida se basa finalmente en revelación, no solo en observación. El Dios que ordenó entrar determina el momento de salir.", "Dibber introduce comunicación directa y prepara una comisión renovada."),
    v(16, "Sal del arca", "Dios ordena a Noé salir con su esposa, hijos y nueras.", "צֵא מִן־הַתֵּבָה", "Tse min-hattevah", "La orden libera a la familia del refugio temporal hacia una vocación pública en la tierra renovada.", "Tse es el imperativo singular de yatsa, «salir». La lista familiar corresponde a la entrada de 7:13."),
    v(17, "Vida para multiplicarse", "Noé debe sacar a todos los animales para que se reproduzcan, sean fecundos y se multipliquen.", "וּפָרוּ וְרָבוּ עַל־הָאָרֶץ", "Ufaru veravu al-haarets", "La bendición creadora es reiterada a las criaturas preservadas. El diluvio no cancela el proyecto de Dios para una tierra llena de vida.", "Parah y ravah, «fructificar» y «multiplicarse», citan el lenguaje de Génesis 1."),
    v(18, "La familia sale", "Noé sale acompañado de su esposa, sus hijos y sus nueras.", "וַיֵּצֵא־נֹחַ", "Vayetse-Noaj", "La obediencia de salida corresponde a la obediencia de entrada. La nueva humanidad comienza como una familia dependiente de la gracia.", "El verbo yatsa se repite del mandato en forma narrativa de cumplimiento."),
    v(19, "Las criaturas salen por familias", "Todos los animales abandonan el arca agrupados según sus familias.", "לְמִשְׁפְּחֹתֵיהֶם", "Lemishpejotehem", "El orden de la salida reafirma continuidad y diversidad. La preservación tuvo como finalidad devolver vida organizada a la tierra.", "Mishpajah significa familia, clan o agrupación; no es una categoría taxonómica técnica."),
    v(20, "El primer altar", "Noé construye un altar y ofrece holocaustos de animales y aves limpios.", "וַיִּבֶן נֹחַ מִזְבֵּחַ", "Vayiven Noaj mizbeaj", "La primera respuesta registrada fuera del arca es adoración. Noé reconoce que la vida preservada pertenece a Dios y usa la provisión adicional de animales limpios.", "Mizbeaj es «altar»; olot son ofrendas totalmente quemadas que ascienden en humo."),
    v(21, "Promesa en medio de la condición humana", "Dios recibe favorablemente la ofrenda y decide no volver a maldecir el suelo ni destruir así toda vida, aunque el corazón humano se incline al mal desde la juventud.", "וַיָּרַח יְהוָה אֶת־רֵיחַ הַנִּיחֹחַ", "Vayyaraj Adonai et-reaj hannijoaj", "La promesa no se basa en una humanidad ahora inocente: el diagnóstico de 6:5 permanece. Dios restringe el juicio por gracia y prepara el marco estable de la historia redentora.", "Reaj nijoaj es «aroma agradable» o apaciguador. La expresión antropomórfica comunica aceptación divina de la ofrenda."),
    v(22, "Los ritmos de la creación", "Mientras permanezca la tierra continuarán siembra y cosecha, frío y calor, verano e invierno, día y noche.", "עֹד כָּל־יְמֵי הָאָרֶץ", "Od kol-yeme haarets", "Dios garantiza estabilidad cósmica para la vida y la misión humana. La promesa no niega desastres locales ni el juicio final; asegura que no habrá otra des-creación diluviana mientras dure el orden presente.", "Las parejas funcionan como merismos: extremos que expresan la totalidad de los ciclos."),
  ],
  [
    { title: "Recordar es actuar fielmente", text: "Dios mueve las aguas y guía la salida conforme a su compromiso con Noé." },
    { title: "La restauración puede ser gradual", text: "El descenso de las aguas, las aves y las fechas forman una escuela de espera." },
    { title: "La salvación desemboca en adoración", text: "Noé responde al nuevo comienzo construyendo un altar." },
    { title: "La gracia sostiene el mundo común", text: "Los ciclos de la tierra continúan pese a la persistencia del pecado humano." },
  ],
  "El «aroma agradable» no debe entenderse como si Dios necesitara alimento o fuera manipulado por el sacrificio. Es lenguaje acomodado que expresa aceptación. La promesa sobre las estaciones establece estabilidad providencial, no inmunidad frente a toda catástrofe ni licencia para descuidar la creación.",
  [
    ["Éxodo 2:3–10", "Otra tevah preserva a Moisés sobre las aguas para iniciar una liberación."],
    ["Salmo 104:5–9", "La contención de las aguas celebra el gobierno creador de Dios."],
    ["Isaías 54:9", "La promesa de Noé sirve como analogía de la fidelidad misericordiosa de Dios."],
    ["2 Corintios 5:17", "La nueva creación en Cristo lleva a su plenitud el patrón de juicio y renovación."],
  ],
);

const genesis9 = c(
  9,
  "Pacto, dignidad y fragilidad",
  "Génesis 9 establece el pacto de Dios con Noé, sus descendientes y toda criatura. La bendición creadora es renovada, la vida humana queda protegida por la imagen divina y el arco funciona como señal de una promesa universal. El final recuerda que el nuevo comienzo todavía necesita redención.",
  [
    v(1, "La bendición renovada", "Dios bendice a Noé y a sus hijos y les ordena ser fecundos, multiplicarse y llenar la tierra.", "פְּרוּ וּרְבוּ וּמִלְאוּ אֶת־הָאָרֶץ", "Peru urevu umilu et-haarets", "La comisión de Génesis 1 continúa después del juicio. Dios no abandona su propósito para la humanidad ni define el futuro solamente por el fracaso pasado.", "Los tres imperativos, «fructifiquen, multiplíquense, llenen», repiten 1:28."),
    v(2, "Un dominio marcado por temor", "Los animales tendrán temor del ser humano y quedan entregados bajo su responsabilidad.", "מוֹרַאֲכֶם וְחִתְּכֶם", "Moraakhem vejittkhem", "El dominio humano persiste, pero la armonía original está dañada. El permiso sobre los animales no legitima crueldad; sigue subordinado al Creador que los preservó.", "Mora y jat significan temor y espanto. Beyedkhem nittanu, «entregados en su mano», expresa autoridad delegada."),
    v(3, "Alimento animal permitido", "Dios permite comer seres vivos, así como había dado las plantas verdes.", "לָכֶם יִהְיֶה לְאָכְלָה", "Lakhem yihyeh leokhlah", "La dieta se amplía explícitamente en el nuevo orden. El don queda inmediatamente limitado por respeto a la vida representada en la sangre.", "Remes aquí abarca animales móviles; ke-yereq esev remite a la provisión vegetal de 1:29."),
    v(4, "La sangre pertenece a Dios", "No se debe comer carne que conserve su sangre vital.", "בָּשָׂר בְּנַפְשׁוֹ דָמוֹ", "Basar benafsho damo", "La prohibición enseña que recibir alimento no equivale a apropiarse de la vida como dueño absoluto. La legislación posterior desarrollará esta relación entre vida y sangre.", "Nefesh puede significar vida, persona o ser viviente; dam es sangre. La frase vincula ambos conceptos."),
    v(5, "Dios exige cuenta por la vida", "Dios demandará la sangre humana tanto de animales como de otros seres humanos.", "אֶת־דִּמְכֶם לְנַפְשֹׁתֵיכֶם אֶדְרֹשׁ", "Et-dimkhem lenafshoteikhem edrosh", "La vida humana no queda a merced del fuerte. Dios se presenta como defensor y juez, y hace responsable a todo agente que la destruya.", "Darash significa «buscar», «requerir» o «pedir cuentas». Ish ajiv, «cada uno de su hermano», recalca responsabilidad humana."),
    v(6, "La imagen divina protege al prójimo", "Quien derrama sangre humana queda sujeto a una sanción humana porque Dios hizo al ser humano a su imagen.", "כִּי בְּצֶלֶם אֱלֹהִים", "Ki betselem Elohim", "La caída no borró la imagen de Dios. El versículo fundamenta la especial dignidad de toda persona y la administración pública de justicia; no autoriza venganza privada ni desprecio por el debido proceso.", "Shofekh yishafekh forman una correspondencia jurídica de derramar sangre. Tselem es «imagen»."),
    v(7, "Llenen abundantemente", "Dios vuelve a llamar a Noé y sus hijos a multiplicarse y poblar la tierra.", "שִׁרְצוּ בָאָרֶץ וּרְבוּ־בָהּ", "Shirtsu vaarets urevu-vah", "La repetición rodea las normas sobre vida con una afirmación positiva: el propósito es que la vida florezca bajo protección.", "Sharats comunica abundante proliferación; ravah vuelve a expresar multiplicación."),
    v(8, "Dios toma la iniciativa", "Dios habla a Noé y a sus hijos.", "וַיֹּאמֶר אֱלֹהִים אֶל־נֹחַ", "Vayomer Elohim el-Noaj", "El pacto que sigue no es negociado por partes iguales. Dios anuncia soberanamente una obligación que él mismo asume.", "La inclusión explícita de los hijos extiende la promesa más allá de la experiencia individual de Noé."),
    v(9, "Pacto con las generaciones", "Dios establece su pacto con Noé, sus hijos y la descendencia futura.", "מֵקִים אֶת־בְּרִיתִי", "Meqim et-beriti", "El alcance generacional permite que toda la humanidad posterior viva dentro de esta paciencia providencial.", "Meqim es participio de «establecer» o «mantener en vigor»; zera ajareikhem es descendencia futura."),
    v(10, "Pacto con toda criatura", "El compromiso incluye aves, ganado, animales y todo ser que salió del arca.", "כָּל־נֶפֶשׁ הַחַיָּה", "Kol-nefesh hajjayah", "La alianza no es exclusivamente antropocéntrica. El Creador vincula el bienestar humano con el del mundo animal preservado.", "Nefesh jayyah es «ser viviente». La lista insiste en kol, «todo»."),
    v(11, "No habrá otro diluvio destructor", "Dios promete que ninguna carne será exterminada otra vez por un diluvio ni la tierra será destruida de esa manera.", "וְלֹא־יִהְיֶה עוֹד מַבּוּל", "Velo-yihyeh od mabbul", "La promesa se refiere específicamente a un diluvio que destruya toda carne y la tierra. No elimina juicios locales ni el juicio final, pero garantiza estabilidad histórica.", "Lo yikkaret, «no será cortada», usa lenguaje de destrucción; mabbul conserva su sentido técnico."),
    v(12, "Una señal para siempre", "Dios designa una señal del pacto entre él, la humanidad y todas las criaturas por generaciones.", "אוֹת הַבְּרִית", "Ot habberit", "La señal visible confirma una palabra ya dada; no crea el pacto ni depende de que humanos la activen.", "Ot es «señal». Dorot olam puede significar generaciones perpetuas dentro del horizonte pactal."),
    v(13, "El arco en las nubes", "Dios coloca su arco en la nube como señal del pacto con la tierra.", "אֶת־קַשְׁתִּי נָתַתִּי בֶּעָנָן", "Et-qashti natatti beanan", "El arco, instrumento que puede representar guerra, aparece suspendido en las nubes. La imagen comunica que Dios limita el juicio diluviano y ofrece una señal pública de paz pactal.", "Qeshet significa tanto arco de guerra como arco visible en el cielo. Natatti puede traducirse «he puesto»."),
    v(14, "La señal aparece", "Cuando Dios cubra la tierra de nubes, el arco se verá en ellas.", "וְנִרְאֲתָה הַקֶּשֶׁת בֶּעָנָן", "Veniratah haqqeshet beanan", "La misma nube que podría despertar memoria del juicio contiene una señal de misericordia. La promesa transforma el modo de interpretar la tormenta.", "Niratah es forma pasiva: «será vista» o «aparecerá»."),
    v(15, "Dios recordará el pacto", "Dios recordará su compromiso con toda criatura y las aguas no volverán a destruir toda carne.", "וְזָכַרְתִּי אֶת־בְּרִיתִי", "Vezakharti et-beriti", "Como en 8:1, recordar significa actuar conforme al pacto, no recuperar información perdida. La seguridad descansa en la fidelidad divina.", "Beriti asher beni uvenekhem expresa relación pactal «entre mí y ustedes»."),
    v(16, "Pacto eterno visible", "Al mirar el arco, Dios recordará el pacto duradero con todos los seres vivos.", "לִזְכֹּר בְּרִית עוֹלָם", "Lizkor berit olam", "La repetición adapta la promesa a la comprensión humana: la señal certifica que cada generación vive bajo paciencia sostenida.", "Olam puede indicar perpetuidad o duración indefinida según el pacto; aquí abarca el orden terrestre prometido."),
    v(17, "La señal confirmada", "Dios identifica nuevamente el arco como señal del pacto con toda carne sobre la tierra.", "זֹאת אוֹת־הַבְּרִית", "Zot ot-habberit", "El cierre evita reducir el símbolo a sentimiento subjetivo. Su significado proviene de la declaración de Dios y su alcance es universal.", "Zot, «esta», señala de modo enfático la marca visible ya explicada."),
    v(18, "Los tres hijos y Canaán", "Sem, Cam y Jafet salen del arca; Cam es identificado como padre de Canaán.", "וְחָם הוּא אֲבִי כְנָעַן", "VeJam hu avi Khenaán", "La mención anticipada de Canaán prepara el episodio familiar y sus consecuencias. Noé y sus hijos son receptores del pacto, pero no personas sin pecado.", "Avi puede indicar padre o antepasado; aquí establece la relación genealógica inmediata."),
    v(19, "Una humanidad común", "De los tres hijos de Noé se dispersa la población de toda la tierra.", "נָפְצָה כָל־הָאָרֶץ", "Naftsa khol-haarets", "Todas las naciones de Génesis 10 comparten origen familiar y dignidad común. El texto excluye teorías de humanidades separadas.", "Nafats significa «dispersarse» o «extenderse»."),
    v(20, "Noé cultiva una viña", "Noé comienza a trabajar la tierra y planta una viña.", "אִישׁ הָאֲדָמָה", "Ish haadamah", "El hombre de la tierra retoma la vocación adámica. La agricultura es buena; el episodio mostrará cómo un don puede usarse sin dominio propio.", "Ish haadamah significa «hombre del suelo» o agricultor. Vayyitta significa «plantó»."),
    v(21, "Embriaguez y desnudez", "Noé bebe vino, se embriaga y queda descubierto dentro de su tienda.", "וַיִּשְׁתְּ וַיֵּשְׁכָּר", "Vayyesht vayyeshkar", "El salvado del diluvio sigue siendo un pecador vulnerable. La escena enlaza vino, pérdida de control y vergüenza, demostrando que el juicio externo no cura el corazón.", "Shakhar es «embriagarse». Vayyitgal, «se descubrió», viene de una raíz asociada con desnudez o exposición."),
    v(22, "Cam ve y divulga", "Cam ve la desnudez de su padre y se lo cuenta a sus hermanos afuera.", "וַיַּרְא אֵת עֶרְוַת אָבִיו", "Vayyar et ervat aviv", "El relato contrasta su reacción con la protección respetuosa de los hermanos. El texto no especifica un acto sexual ni justifica añadirlo sin evidencia; el agravio evidente incluye exposición deshonrosa.", "Raah es «ver»; ervah, «desnudez». Vayyagged, «contó», convierte la vulnerabilidad privada en noticia externa."),
    v(23, "Sem y Jafet cubren", "Los hermanos caminan hacia atrás y cubren a su padre sin mirar su desnudez.", "וּפְנֵיהֶם אֲחֹרַנִּית", "Ufneihem ajorannit", "Su conducta combina verdad y misericordia: no niegan la condición de Noé, pero rechazan explotarla. Honrar aquí significa proteger la dignidad del vulnerable.", "Simlah es manto. La triple referencia a rostros vueltos recalca la intención respetuosa."),
    v(24, "Noé despierta", "Noé se recupera del vino y conoce lo que su hijo menor le hizo.", "וַיֵּדַע אֵת אֲשֶׁר־עָשָׂה־לוֹ", "Vayyeda et asher-asah-lo", "La narración no explica cómo lo sabe ni amplía el acto. Esa sobriedad aconseja no construir doctrinas sobre detalles ausentes.", "Haqqatan puede significar «el menor» o «el pequeño»; la identificación genealógica admite discusión."),
    v(25, "Canaán bajo maldición", "Noé declara a Canaán maldito y siervo de siervos para sus hermanos.", "אָרוּר כְּנָעַן", "Arur Khenaán", "La sentencia se dirige a Canaán, no a una etnia moderna ni a todos los descendientes de Cam. Su uso histórico para defender esclavitud racial contradice el texto y la dignidad de 9:6.", "Eved avadim es superlativo: «siervo de siervos». La razón de nombrar a Canaán se relaciona con el horizonte narrativo posterior."),
    v(26, "El Dios de Sem", "Noé bendice al Señor, Dios de Sem, y sitúa a Canaán como siervo.", "בָּרוּךְ יְהוָה אֱלֹהֵי שֵׁם", "Barukh Adonai Elohe Shem", "La bendición recae primero sobre Dios, fuente del bien de Sem. La línea de revelación que llegará a Abraham emerge dentro de esta familia.", "Barukh aquí alaba a YHWH. La construcción «Dios de Sem» expresa relación especial."),
    v(27, "Jafet ensanchado", "Noé pide que Dios ensanche a Jafet y le permita habitar en las tiendas de Sem.", "יַפְתְּ אֱלֹהִים לְיֶפֶת", "Yaft Elohim leYefet", "El juego con el nombre expresa expansión y posible comunión con la bendición de Sem. La frase admite interpretaciones sobre quién habita en las tiendas, por lo que conviene evitar esquemas étnicos rígidos.", "Yaft, «ensanche», resuena con Yefet. Yishkon puede tener como sujeto a Jafet o, según algunos, a Dios."),
    v(28, "Trescientos cincuenta años", "Noé vive trescientos cincuenta años después del diluvio.", "אַחַר הַמַּבּוּל", "Ajar hammabbul", "La larga vida enlaza el mundo anterior con numerosas generaciones posteriores y confirma continuidad histórica tras el juicio.", "Ajar marca el período posterior; la cifra prepara el total del versículo siguiente."),
    v(29, "La muerte de Noé", "Noé alcanza novecientos cincuenta años y muere.", "וַיְהִי כָּל־יְמֵי־נֹחַ", "Vayehi kol-yeme-Noaj", "El nuevo comienzo no revierte la sentencia de muerte de Génesis 3. Incluso el justo preservado necesita una salvación más profunda que el arca.", "Vayamot recupera el estribillo de Génesis 5 y cierra la sección de Noé."),
  ],
  [
    { title: "La imagen de Dios permanece", text: "Toda vida humana conserva una dignidad que exige protección y justicia." },
    { title: "El pacto alcanza a la creación", text: "Dios promete estabilidad a la humanidad, los animales y la tierra." },
    { title: "La señal descansa en la palabra", text: "El arco garantiza una promesa iniciada y recordada por Dios." },
    { title: "La gracia no elimina la lucha con el pecado", text: "Noé sale del arca salvado, pero la vergüenza reaparece en su familia." },
  ],
  "La llamada «maldición de Cam» es una denominación imprecisa: Génesis 9:25 nombra a Canaán. El pasaje jamás clasifica personas por color de piel y no autoriza esclavitud racial. Las interpretaciones que lo usaron con ese fin son una grave distorsión exegética y moral.",
  [
    ["Levítico 17:10–14", "La ley desarrolla la relación entre sangre y vida perteneciente a Dios."],
    ["Isaías 54:9–10", "El pacto de Noé respalda la certeza de la misericordia divina."],
    ["Hechos 17:26", "La humanidad comparte un origen y vive bajo la soberanía providencial de Dios."],
    ["Santiago 3:9", "La imagen divina sigue fundamentando el trato digno al prójimo caído."],
  ],
);

const genesis10 = c(
  10,
  "Las familias de las naciones",
  "Génesis 10, conocido como la tabla de las naciones, traza el mundo posterior al diluvio mediante familias, territorios y lenguas. No pretende ofrecer una taxonomía moderna de todas las etnias, sino mostrar que la diversidad de pueblos surge de una humanidad común y permanece bajo el gobierno de Dios.",
  [
    v(1, "Las generaciones de los hijos de Noé", "Se presenta la descendencia de Sem, Cam y Jafet nacida después del diluvio.", "וְאֵלֶּה תּוֹלְדֹת בְּנֵי־נֹחַ", "Veeleh toledot bene-Noaj", "La fórmula toledot abre un mapa genealógico y geográfico. Los sobrevivientes del arca se convierten en familias de naciones, cumpliendo el mandato de multiplicarse.", "Toledot puede significar generaciones, descendencia o historia familiar."),
    v(2, "Los hijos de Jafet", "La línea de Jafet comienza con Gomer, Magog, Madai, Javán, Tubal, Mesec y Tiras.", "בְּנֵי יֶפֶת", "Bene Yefet", "Los nombres representan antepasados y pueblos asociados principalmente con regiones al norte y oeste de Israel. El capítulo organiza el horizonte conocido desde la perspectiva bíblica.", "En genealogías antiguas, un nombre puede designar individuo, clan o territorio relacionado."),
    v(3, "Los descendientes de Gomer", "Askenaz, Rifat y Togarma descienden de Gomer.", "וּבְנֵי גֹּמֶר", "Uvene Gomer", "La ramificación muestra cómo una casa principal se diversifica en grupos históricos. Identificaciones geográficas exactas deben mantenerse con modestia.", "La forma Rifat presenta variantes antiguas; los nombres se transliteran de modos distintos entre versiones."),
    v(4, "Los descendientes de Javán", "Elisa, Tarsis, Quitim y Dodanim pertenecen a la línea de Javán.", "וּבְנֵי יָוָן", "Uvene Yavan", "Javán se asocia ampliamente con pueblos egeos y griegos; Tarsis y Quitim aparecen después como regiones marítimas. La lista anticipa una red de pueblos, no aislamiento.", "Dodanim aparece como Rodanim en algunos manuscritos y en 1 Crónicas 1:7; una diferencia gráfica antigua explica la variante."),
    v(5, "Costas, lenguas y naciones", "De estos grupos se distribuyen pueblos marítimos por tierras, lenguas, clanes y naciones.", "אִישׁ לִלְשֹׁנוֹ", "Ish lilshono", "La diversidad lingüística se menciona temáticamente antes del relato de Babel, porque el capítulo ofrece el resultado organizado y Génesis 11 explicará su dispersión.", "Lashon significa lengua tanto como órgano como idioma. Goy y mishpajah son nación y clan."),
    v(6, "Los hijos de Cam", "La línea de Cam incluye Cus, Mizraim, Fut y Canaán.", "וּבְנֵי חָם", "Uvene Jam", "Los nombres orientan la atención hacia África nororiental, zonas vecinas y Canaán, importantes para la historia posterior de Israel.", "Mitsrayim es la forma hebrea habitual de Egipto; el sufijo dual puede reflejar Alto y Bajo Egipto."),
    v(7, "Las ramas de Cus", "Se enumeran los hijos de Cus y, por medio de Raama, Seba y Dedán.", "וּבְנֵי כוּשׁ", "Uvene Khush", "La lista relaciona pueblos a ambos lados del mar Rojo y muestra redes de parentesco y comercio en el mundo antiguo.", "Seba y Sheba son nombres distintos en hebreo aunque algunas transliteraciones los acercan."),
    v(8, "Nace Nimrod", "Cus engendra a Nimrod, quien comienza a ser poderoso en la tierra.", "הוּא הֵחֵל לִהְיוֹת גִּבֹּר", "Hu hejel lihyot gibbor", "La genealogía se detiene para perfilar a un fundador de poder. «Comenzó» introduce una concentración política que prepara ciudades ligadas a Babel.", "Gibbor puede significar poderoso, héroe o guerrero; por sí solo no determina una valoración moral completa."),
    v(9, "Poderoso cazador", "Nimrod llega a ser un poderoso cazador delante del Señor y origina un proverbio.", "גִּבֹּר־צַיִד לִפְנֵי יְהוָה", "Gibbor-tsayid lifne Adonai", "«Delante del Señor» puede señalar notoriedad bajo la mirada divina, no aprobación automática. Su fama humana queda siempre expuesta al juicio de Dios.", "Tsayid es caza; lifne YHWH significa literalmente «ante el rostro del Señor»."),
    v(10, "El comienzo de su reino", "Babel, Erec, Acad y Calne en Sinar forman el inicio del reino de Nimrod.", "רֵאשִׁית מַמְלַכְתּוֹ", "Reshit mamlakhto", "Es la primera mención explícita de un reino humano en la Biblia. Babel enlaza expansión urbana, poder político y el desafío colectivo narrado después.", "Mamlakhah es reino o dominio. Shinar corresponde a la llanura mesopotámica."),
    v(11, "Ciudades de Asiria", "Desde esa región se extiende hacia Asiria y se edifican Nínive, Rehobot-Ir y Cala.", "וַיִּבֶן אֶת־נִינְוֵה", "Vayiven et-Nineveh", "El texto conecta centros imperiales que más tarde dominarán la historia bíblica. La civilización urbana puede expresar creatividad y, a la vez, poder opresivo.", "La sintaxis permite que el sujeto sea Nimrod o que Assur saliera y edificara; las traducciones difieren legítimamente."),
    v(12, "Resén y la gran ciudad", "Resén se ubica entre Nínive y Cala dentro del gran complejo urbano.", "הִוא הָעִיר הַגְּדֹלָה", "Hi hair haggedolah", "La observación geográfica muestra la escala del asentamiento asirio. La frase «la gran ciudad» puede referirse a Cala o al conjunto metropolitano.", "Los pronombres hebreos permiten cierta ambigüedad en el antecedente de hi."),
    v(13, "Pueblos procedentes de Egipto", "Mizraim da origen a luditas, anamitas, lehabitas y naftuhitas.", "וּמִצְרַיִם יָלַד", "UMitsrayim yalad", "El verbo genealógico atribuye pueblos a un ancestro-territorio. No implica que las naciones funcionen como familias nucleares modernas.", "Los plurales en -im suelen designar colectivos étnicos; su localización exacta no siempre es segura."),
    v(14, "Más ramas y los filisteos", "Se añaden patrusitas, casluhitas y caftoritas; de una de estas líneas proceden los filisteos.", "אֲשֶׁר יָצְאוּ מִשָּׁם פְּלִשְׁתִּים", "Asher yatseu misham Pelishtim", "La nota ubica a un pueblo decisivo para Jueces y Samuel dentro de la misma familia humana. Jeremías y Amós también relacionan a los filisteos con Caftor.", "La posición de la cláusula puede asociarla gramaticalmente con Casluhim, mientras otros textos destacan Caftor; podría reflejar migraciones relacionadas."),
    v(15, "Los primeros hijos de Canaán", "Canaán engendra a Sidón, su primogénito, y a Het.", "אֶת־צִידֹן בְּכֹרוֹ", "Et-Tsidon bekhoro", "La genealogía prepara los pueblos y ciudades de la tierra prometida. Sidón representa el ámbito fenicio y Het a grupos hititas o heteos del entorno cananeo.", "Bekhoro significa «su primogénito». Los nombres personales también funcionan como epónimos de pueblos."),
    v(16, "Tres pueblos cananeos", "Se enumeran jebuseos, amorreos y gergeseos.", "וְאֶת־הַיְבוּסִי", "Veet-hayevusi", "Estos pueblos reaparecerán en las promesas patriarcales y en la entrada de Israel a Canaán. Compartir genealogía no elimina responsabilidad moral ni permite odio étnico.", "El artículo ha- convierte los nombres en designaciones colectivas: «el jebuseo», es decir, el pueblo."),
    v(17, "Otras comunidades cananeas", "También se nombran heveos, araceos y sineos.", "וְאֶת־הַחִוִּי", "Veet-hajjivvi", "La lista conserva memoria de comunidades menores conocidas por el antiguo Israel, aunque su ubicación precisa sea desigual para la arqueología moderna.", "Arqi suele relacionarse con Arqa en el actual Líbano; Sini permanece incierto."),
    v(18, "Dispersión de los clanes", "Se añaden arvadeos, zemareos y hamateos; luego los clanes cananeos se dispersan.", "נָפֹצוּ מִשְׁפְּחוֹת הַכְּנַעֲנִי", "Nafotsu mishpejot hakkenaani", "La expansión transforma una línea genealógica en un mosaico territorial. La geografía concreta prepara los límites descritos a continuación.", "Nafotsu significa «se dispersaron»; mishpejot son clanes o familias extensas."),
    v(19, "Las fronteras de Canaán", "El territorio cananeo se describe desde Sidón hacia Gerar y Gaza, y hacia las ciudades de la llanura.", "וַיְהִי גְּבוּל הַכְּנַעֲנִי", "Vayehi gevul hakkenaani", "Los límites sitúan el relato patriarcal futuro en un espacio real. La mención de Sodoma y Gomorra anticipa la evaluación moral de Génesis 18–19.", "Gevul puede ser frontera o territorio. Las rutas «hasta» delinean extremos más que un mapa cartográfico exhaustivo."),
    v(20, "Resumen de la línea de Cam", "Los descendientes de Cam quedan agrupados por clanes, lenguas, territorios y naciones.", "לְמִשְׁפְּחֹתָם לִלְשֹׁנֹתָם", "Lemishpejotam lilshonotam", "El mismo esquema usado con Jafet afirma orden dentro de la diversidad. Ninguna línea queda fuera de la providencia del Creador.", "La secuencia familias-lenguas-tierras-naciones es una fórmula estructural del capítulo."),
    v(21, "Sem y la familia de Éber", "También nacen descendientes a Sem, antepasado de los hijos de Éber y relacionado con Jafet.", "אֲבִי כָּל־בְּנֵי־עֵבֶר", "Avi kol-bene-Ever", "Éber recibe atención porque su línea conducirá a Abraham. El texto enlaza la historia particular del pueblo hebreo con la humanidad universal.", "La frase ají Yefet haggadol admite «hermano mayor de Jafet» o «hermano de Jafet el mayor»; la edad relativa es discutida."),
    v(22, "Los hijos de Sem", "Elam, Asur, Arfaxad, Lud y Aram forman las ramas principales de Sem.", "בְּנֵי שֵׁם", "Bene Shem", "La lista incluye pueblos de Mesopotamia y Siria. Arfaxad será seleccionado genealógicamente para la línea de la promesa.", "Shem significa «nombre», pero aquí es nombre propio; no debe confundirse sin más con la categoría lingüística moderna «semítica»."),
    v(23, "Los hijos de Aram", "Uz, Hul, Geter y Mas descienden de Aram.", "וּבְנֵי אֲרָם", "Uvene Aram", "Estas ramas sitúan comunidades arameas en el horizonte de la familia de Abraham, cuyos vínculos con Aram serán importantes en Génesis.", "Mash aparece como Mesec en 1 Crónicas 1:17 en algunas tradiciones textuales; no es necesariamente el Mesec de 10:2."),
    v(24, "De Arfaxad a Éber", "Arfaxad engendra a Sala, y Sala engendra a Éber.", "וְאַרְפַּכְשַׁד יָלַד אֶת־שָׁלַח", "VeArpakhshad yalad et-Shelaj", "La narración estrecha el foco hacia la línea que Génesis 11 ampliará hasta Abram. La promesa avanza dentro del conjunto de naciones, no aparte de su historia.", "La Septuaginta y Lucas 3 incluyen a Cainán entre Arfaxad y Sala; el texto hebreo masorético presenta la forma directa usada aquí."),
    v(25, "Peleg y la división", "Éber tiene dos hijos: Peleg, llamado así porque en sus días se divide la tierra, y Joctán.", "כִּי בְיָמָיו נִפְלְגָה הָאָרֶץ", "Ki veyamav niflegah haarets", "La división probablemente anticipa la dispersión de Babel, aunque algunos la relacionan con reparto territorial. El nombre transforma un acontecimiento histórico en memoria familiar.", "Peleg resuena con palag, «dividir». Erets puede significar tierra, territorio o mundo habitado."),
    v(26, "La primera rama de Joctán", "Joctán engendra a Almodad, Selef, Hazar-mavet y Jera.", "וְיָקְטָן יָלַד", "VeYoqtan yalad", "La extensa línea de Joctán suele asociarse con pueblos de Arabia meridional. Su inclusión impide reducir la historia bíblica a las líneas que luego ocupan el centro narrativo.", "Joqtan puede relacionarse con «pequeño»; Jatsarmavet conserva un nombre conocido en Hadramaut, aunque la identificación requiere cautela."),
    v(27, "Más hijos de Joctán", "Hadoram, Uzal y Dicla continúan la lista.", "וְאֶת־הֲדוֹרָם", "Veet-Hadoram", "La enumeración honra la existencia histórica de pueblos apenas desarrollados después. La Escritura los ubica dentro de la familia preservada por Dios.", "Uzal fue relacionado tradicionalmente con Yemen; Dicla puede asociarse con palmeras, pero la etimología no prueba ubicación."),
    v(28, "Obal, Abimael y Seba", "Tres nuevas ramas proceden de Joctán.", "וְאֶת־עוֹבָל", "Veet-Oval", "La repetición genealógica comunica expansión abundante, cumplimiento concreto de la bendición dada a Noé.", "Obal aparece como Ebal en 1 Crónicas 1:22; las variantes reflejan transmisión de nombres poco comunes."),
    v(29, "Ofir, Havila y Jobab", "La lista de hijos de Joctán concluye con Ofir, Havila y Jobab.", "אֶת־אוֹפִר וְאֶת־חֲוִילָה", "Et-Ofir veet-Javilah", "Ofir será conocido por oro y comercio; estos nombres conectan la genealogía con rutas y recursos del mundo bíblico.", "La ubicación de Ofir es debatida entre Arabia, África oriental y otras regiones del comercio antiguo."),
    v(30, "El territorio joctanita", "Su asentamiento se extiende desde Mesa hacia Sefar, región montañosa del oriente.", "הַר הַקֶּדֶם", "Har haqqedem", "La nota convierte la lista de nombres en espacio habitado y movimiento. La humanidad obedece parcialmente el mandato de llenar la tierra mediante migración y asentamiento.", "Qedem puede significar este u oriente y también antigüedad según el contexto; aquí es geográfico."),
    v(31, "Resumen de la línea de Sem", "Los descendientes de Sem se organizan por clanes, lenguas, territorios y naciones.", "לְגוֹיֵהֶם", "Legoyehem", "Sem comparte la misma estructura de diversidad que Jafet y Cam. La futura elección de Abraham será misión de bendición entre las naciones, no prueba de superioridad natural.", "Goyim significa naciones o pueblos; no lleva aquí una valoración negativa."),
    v(32, "De una familia a muchas naciones", "Las familias de los hijos de Noé forman las naciones que se dispersan sobre la tierra después del diluvio.", "וּמֵאֵלֶּה נִפְרְדוּ הַגּוֹיִם", "Umeelleh nifredu haggoyim", "El resumen afirma unidad de origen y pluralidad histórica. Génesis 11 explicará la dispersión y Génesis 12 anunciará bendición para todas estas familias por medio de Abram.", "Nifredu significa «se separaron» o «se distribuyeron». La fórmula baarets enlaza nación y territorio."),
  ],
  [
    { title: "La humanidad tiene un origen común", text: "La diversidad de pueblos nace de la familia preservada, no de humanidades con distinto valor." },
    { title: "Dios gobierna la geografía humana", text: "Familias, lenguas y territorios se desarrollan dentro de su propósito providencial." },
    { title: "El poder humano es ambiguo", text: "Ciudades y reinos exhiben capacidad cultural, pero también preparan concentraciones de orgullo y dominio." },
    { title: "La elección servirá a las naciones", text: "La línea de Sem conduce a Abraham, por quien Dios promete bendecir todas las familias enumeradas." },
  ],
  "La tabla de las naciones no debe utilizarse para construir jerarquías raciales ni para forzar cada nombre antiguo sobre un Estado moderno. Combina genealogía, geografía y memoria étnica desde el horizonte del antiguo Israel; su afirmación teológica central es la unidad de la humanidad dentro de una diversidad real.",
  [
    ["Deuteronomio 32:8", "La distribución de las naciones se contempla bajo el gobierno del Altísimo."],
    ["1 Crónicas 1:5–23", "El cronista conserva estas líneas al situar a Israel dentro de la historia humana."],
    ["Hechos 17:26–27", "Pablo afirma un origen común y tiempos y límites determinados para que los pueblos busquen a Dios."],
    ["Apocalipsis 7:9", "La redención culmina con una multitud de toda nación, pueblo y lengua ante el Cordero."],
  ],
);

